('Павел Воля',
'https://afisha.yandex.ru/samara/standup/pavel-volia-tour?source=rubric',
'Павел Воля — самый известный и дерзкий комик России. Его телепроекты выходят в прайм-тайм, видео с его стендапом набирают десятки миллионов просмотров, а билеты на концерты раскупаются задолго до концерта.

Ты сможешь увидеть не просто смешное выступление комика. В каждой шутке Павла зрители узнают себя, ведь говорит он об обычных вещах, которые окружают нас, о простых и понятных ценностях. Павел шутит смело, смешно и понятно. Его простой, но пронзительный юмор покорит каждого зрителя.',
