('Вокзал на троих',
'https://afisha.yandex.ru/samara/theatre_show/vokzal-na-troikh-sovremennyi-teatr-antreprizy?source=rubric',
'«Вокзал на троих» — история о трёх разных людях, по стечению обстоятельств, вынужденных провести вместе вечер в привокзальном кафе. Согласитесь, трудно представить за одним столом популярного телеведущего, женщину, недавно вышедшую из мест не столь отдалённых и бармена. Именно благодаря этой троице, привокзальное кафе «Тупик» на одну ночь становится тем местом, где мир гламура и глянца сталкивается с проблемами реальной российской действительности.

Поставил спектакль режиссер Роман Самгин, ученик Марка Захарова, обладатель премии за лучшую режиссуру «Московский дебют» и премии за лучший спектакль на театральном фестивале в Брно. Как и в других его работах, в «Вокзале для троих» через смех и слезы ярко раскрываются человеческие судьбы и характеры.

