('Денис Мацуев и друзья. Гала-концерт с оркестром',
'https://afisha.yandex.ru/samara/concert/denis-matsuev-i-druzia-gala-kontsert-s-orkestrom?source=rubric',
'Музыкальный фестиваль «Денис Мацуев представляет: диалог поколений» проходит по всей России. Он объединяет на сцене музыкантов разных поколений, представителей российской исполнительской школы — от юных звёзд до всемирно известных музыкантов. Художественный руководитель Фестиваля — российский музыкант и общественный деятель, народный артист РФ, лауреат Государственной премии РФ Денис Мацуев.

Программа:
Открытая репетиция для школьников ДМШ и ДШИ, студентов музыкального училища и музыкальных вузов (с 15.00 до 18.00)

