— Чайковский. «Меланхолическая серенада» для скрипки с оркестром си-бемоль минор, соч. 26
«Вальс-скерцо» для скрипки с оркестром, соч. 34
Солистка — Стефания Поспехина (скрипка)
— Глазунов. «Песнь Менестреля» для виолончели с оркестром, соч. 71
— Сен-Санс. Интродукция и рондо каприччиозо для скрипки с оркестром, соч. 28 (переложение для виолончели с оркестром)
Солист — Тихон Евланов (виолончель)
— Моцарт. Речитатив и ария графини из оперы «Свадьба Фигаро» (E Susanna Non Vien!...Dove Sono I Bei Momenti)
— Чайковский. Речитатив и ариозо Натальи из оперы «Опричник» («Почудились мне будто голоса»)
— Пуччини. Ария Лауретты из оперы «Джанни Скикки»
Солистка — Валентина Феденева (сопрано)

II отделение
— Моцарт. Финал концерта № 21 для фортепиано с оркестром до мажор, К. 467
Солистка — Варвара Заруднева (фортепиано)
— Бетховен. Концерт № 5 для фортепиано с оркестром ми-бемоль мажор («Император»), соч. 73
Солист — Денис Мацуев (фортепиано)

