('Мираж',
'https://afisha.yandex.ru/samara/concert/mirazh-2025-05-22?source=rubric',
'Имя Алексея Горбашова стало известно широкой публике в конце 80-х, когда он вошёл в число лучших гитаристов страны по итогам национального хит-парада «Звуковая дорожка».

Соло Алексея Горбашова украсили песни многих известных исполнителей — Дмитрия Маликова, групп «Любэ», «Маленький принц» и др. А участие Алексея в группе «Мираж» стало поистине судьбоносным, ведь его мелодии определили звучание песен группы «Мираж» и сделали группу узнаваемой.

В 90-м году в группе «Мираж» появилась Екатерина Болдышева, с чьим приходом «Мираж» стал «живым» коллективом, а голос Екатерины — визитной карточкой группы.

Возрождение легендарного «Миража» произошло в 2004-м, когда Алексей Горбашов и Екатерина Болдышева на один вечер собрали всех участников группы на сцене в «Олимпийском».

В 2007 году за вклад в отечественную культуру Алексей Горбашов и Екатерина Болдышева были удостоены медалей и дипломов «Профессионал России».

В настоящее время группа не перестаёт удивлять слушателей новыми хитами, непрестанно экспериментируя, но оставаясь при этом востребованной и узнаваемой.

Их видеоролики имеют миллионы просмотров. Как говорят сами музыканты, у них нет задачи остаться навсегда в 90-х, и сегодня они делают ставку на новые песни, в которых есть всё, что нравится поклонникам: современные танцевальные ритмы, рок-гитара и чувственный женский вокал.',
