'Markul представит публике новый долгожданный альбом Make Depression Great Again, а также порадует своими главными хитами. Приготовьтесь к мощному шоу!

Markul — яркий представитель современного русского рэпа, постоянно экспериментирующий с разными жанрами и не теряющий своего оригинального стиля. В 2018 году на свет появилась Great Depression — первая большая и прорывная работа Марка, в которой он откровенно рассказывает о своих переживаниях, страхах, сомнениях и надеждах. В 2020-м году, после завершения аншлагового тура Before I Disappear, музыкант сосредоточился на написании нового материала. Итогом этой работы стала концептуальная пластинка Sense Of Human, которую артист представил большом Pressure Tour.

2024 год завершился для Марка релизом Make Depression Great Again, ставшего продолжением культовой пластинки. Здесь артист делится со слушателями самыми личными эмоциями, о которых ранее никогда еще не говорил, а также мастерски лавирует между жанрами.

Грандиозная презентация нового альбома прошла 20 декабря 2024 года в московской ВТБ Арена при полном солд-ауте. Теперь время погружаться в «великую депрессию» наступило для всех остальных городов.',
