Только выступать в нём будет не профессионал из Нью-Йорка, а обычные мужики с металлургического завода, которые, правда, танцевать-то не умеют.

На протяжении всего спектакля смельчаки отчаянно пытаются научиться не совсем обычному и нелёгкому искусству, преодолевая внешние и внутренние препятствия.

