'Второе дыхание для целого поколения!

Её голос — это отсылка к первой любви, молодости, танцам до утра. Ева Польна — артистка, творчество которой каждый раз удивляло новизной и экспериментаторством. А строчки ее песен — личные мантры многих мечтателей.

Это отличный шанс окунуться в состояние невесомости, в которое неминуемо погружает ее мелодичный голос: «Я шатаюсь по улицам. Где же мой берег? Это солнце меня изнутри выжигает».

На ее концертах собираются не просто зрители, а родственные души, потому что вайб — общий. Каждый аккорд — узнаваем, каждая строчка — про нас.

Это общее дыхание зала, возможность вновь прожить любимые мелодии, которые до сих пор звучат на вечеринках, в наушниках, в машине, в сердце. Это вечер для тех, кто помнит. Для тех, кто скучал.

