'«Лошадка», «Верхом на звезде», «Одна она», «Три слова» — хиты, который знает каждый уважающий себя фанат рок-музыки. Именно эти песни принесли Найк у Борзову всероссийскую любовь и славу, а его вокал не спутать ни с одним другим голосом в мире.

Найк Борзов — певец, композитор, поэт и родоначальник инди-движения в России. Сольную карьеру музыкант начал в 90-х. На всю страну прославился в нулевых сначала суперхитом «Лошадка», а затем двумя каноническими пластинками «Супермен» и «Заноза».

