'Группа «Пилот» представляет новую концертную программу «Пересекая магистрали страны». Ставшая крылатой фраза из песни «Рок» диктует безальтернативно: будет настоящий рок, в рамках которого музыканты исполнят проверенные концертные боевики и уже давно не звучавшие, но такие любимые, заслушанные до дыр песни. Конечно, и это ещё не всё.

Илья Кнабенгоф: «От лица ВИА «Пилот» хочу сообщить вам, что концертная программа уже вовсю обсуждается и готовится. В этот формат мы сейчас собираем те композиции, которые уже давно не играли, вспомним то, что несколько лет уже оставалось вне нашего общего внимания. Обязательно зацепим композиции из «тяжеляка», и в целом, мы хотим понабрать «редкостей» и смешать их с хитами. Ещё один музыкальный сюрприз — мы с ребятами задумали восстановить что-то из совсем старого, сделаем, как это модно говорить, реюнион».

Важная часть новой программы — трансляция на экранах видеоряда с концептуальными сюжетами и художественными символами, которые отражают настроение и тему каждой композиции.

К слову, уже в 2024 году на концертах гости могли заметить, что группа начала обновлять видеоряд, и вас ждут новые незаурядные видеосценарии.',
