('Полёт над гнездом кукушки',
'https://afisha.yandex.ru/samara/theatre_show/spektakl-poliot-nad-gnezdom-kukushki?source=rubric',
'Роман Кена Кизи «Полёт над гнездом кукушки» («One Flew Over the Cuckoo’s Nest») — это культовое произведение, манифест «поколения рассерженных» 60-х годов прошлого века. А снятый по нему и получивший пять «Оскаров» фильм Милоша Формана сделал его поистине легендой.

Психиатрическая лечебница, в которой происходит все действие, однозначно является образом окружающего нас мира, системы, делающей людей послушными и безропотными. Какой выход? Сопротивление, протест, бунт. Вот и появляется в клинике главный герой — бунтарь Макмэрфи, личность яркая и жизнерадостная, остроумная и изобретательная. А главное — сильная и бесстрашная. И система трещит по швам, а ее воплощение — старшая сестра Рэтчед вступает с разрушителем всех устоев в смертельную схватку.

