'Жанр спектакля по пьесе современного драматурга Валерия Золотовицкого театр обозначил как «спектакль-концерт». Действительно, здесь много поют , звучат любимые шлягеры 60-х, 70-х, 80-х.

На окраине провинциального города в деревянном доме, предназначенном под снос, живут на чемоданах герои, в ожидании скорого переезда в новые квартиры. Свободное время проводят во дворе. На этом маленьком клочке земли происходят важные события : здесь влюбляются, счастливо и без взаимности, ссорятся, ищут смысл жизни, - словом, живут жизнью обыкновенных людей. И еще поют. Проходят годы, меняется репертуар, а оптимизм обитателей дома не убывает.

