Вы помните те ощущения, когда достали тот самый винил Dark Side of the Moon? Слетали на Луну и обратно вместе с Гилмором, Уотерсом, Райтом и Мэйсоном. Или может ваше первое знакомство с группой началось с Another Brick In the Wall? Хотя, возможно, вас не оставила равнодушным композиция High Hopes из альбома Division Bell?

На выступлении Floyd Universe — Symphony Tribute Show вы услышите все эти и другие не менее значимые хиты легендарной группы. Симфонический оркестр подчёркивает всю эмоциональность и глубину музыки Pink Floyd, придавая великим произведениям новые краски.

Floyd Universe — Symphony Tribute Show — это около двух часов «живого» звука, ярких видеоинсталляций и крутого лазерного шоу!

