('Константин Райкин. Самое любимое',
'https://afisha.yandex.ru/samara/monoperformance/konstantin-raikin-samoe-liubimoe?source=rubric',
'Константин Аркадьевич Райкин — художественный руководитель Государственного театра «Сатирикон» им Аркадия Райкина, народный артист России, режиссер, лауреат Государственных премий РФ, четырежды лауреат Национальной премии «Золотая Маска», лауреат премии Фонда Станиславского, премий «Хрустальная Турандот», «Чайка», «Кумир», «Триумф», художественный руководитель «Высшей школы сценических искусств», профессор.

Моноспектакль-концерт «Самое любимое» — это высокая поэзия, пропущенная через сердце, рассказы признанного театрального лидера и, конечно, воспоминания.

Воспоминания о начале творческого пути, о детских увлечениях, о сомнениях в выборе профессии, юношеских увлечениях спортом, животным миром, упорное нежелание следовать семейным актерским традициям — обо всем этом Райкин не рассказывает, а играет маленькие миниатюры. Особое место занимают воспоминания об отце, этом Гении сцены, слава которого пересекла границы Советского Союза. Зритель, как бы, прослеживает его жизненный путь до блестящего поступления в Театральное училище им. Щукина.

В основной части своего моноспектакля-концерта Константин Райкин читает стихи величайших поэтов, любовь к которым сопутствовала всей его жизни. «Самое любимое» — это о профессии, об отце и поэзии. Народный артист СССР Богдан Ступка, безвременно ушедший из жизни в 2012 году, незадолго до смерти был на этом концерте Райкина и после концерта сказал: «Никто в мире так не читает (надо понимать играет) стихи как Константин Райкин!»

Со сцены звучат стихи Давида Самойлова, Николая Заболоцкого, Николая Рубцова, Осипа Мандельштама, Лопе де Вега, Александра Пушкина.

Приходите за вдохновением!',
