'6 рассказов о любви.

Рассказанные с полной искренностью и откровенностью, эти истории одновременно оставляют чувство радости и грусти, восторга и сожаления, трогают самые сокровенные уголки души — ведь «у каждого из нас найдётся какое-нибудь особенно дорогое любовное воспоминание или какой-нибудь особенно тяжкий любовный грех».

