('Николай Фефилов',
'https://afisha.yandex.ru/samara/concert/nikolai-fefilov?source=rubric',
'«...Можно восхищаться феноменальным пианизмом и виртуозностью, не знающей предела, рельефностью полифонических голосов и деталей фактуры, совершенством формы... Но все это не поможет постичь тайну одухотворенной жизни в звуках рояля. Это чудо», — писала «Самарская газета» о пианисте.

Пианист, лауреат и дипломант международных конкурсов, солист Самарской государственной филармонии, артист «Форте-квартета» Самарской государственной филармонии Инициатор и художественный руководитель российско-германского проекта «Музыкальный вечер для друзей», художественный руководитель Поволжского фестиваля семейных камерных ансамблей (грант Правительства Самарской области). Обладатель губернской творческой премии им. Гилария Беляева.

Участник международных фестивалей «Наследие» (Москва, 1990, 1992), современной музыки (Прага, 1991), «Музыка без границ» (Тольятти, 2002), «Весна в России» (Москва, 2003), «Два дня и две ночи» (Одесса, 2005), «Картинки с выставки» (Нижний Новгород, 2005) и др.

Выступал с сольными программами в городах России, Чехии, Украины, ЮАР, с симфоническими оркестрами Московской, Казанской, Львовской, Самарской, Тольяттинской, Оренбургской филармоний. В составе официальных культурных делегаций представлял Самарскую область в Индии, Китае, Армении, Азербайджане, Чеченской республике.

В 1992 году Николай Фефилов записал компакт-диск с фортепианной музыкой Алексея Станчинского (Etcetera, Голландия), в 2003 году — с фортепианными квартетами Брамса, Шумана. Имеет запись в фонде «Радио России» («15 концертных фуг» Алемдара Караманова). Записи Николая Фефилова регулярно транслируют радиостанции «Орфей» (Россия), ВВС (Великобритания), АВС (Канада).

Доцент Самарской государственной академии культуры и искусств.

Программа:
Шопен. Ноктюрны
Дебюсси. 12 прелюдий для фортепиано (I тетрадь)

Исполнители:
Лауреат международных конкурсов Николай Фефилов (фортепиано)

