('Нам нужна одна Победа',
'https://afisha.yandex.ru/samara/concert/nam-nuzhna-odna-pobeda-2025-05?source=rubric',
'«Нам нужна одна Победа» — концертная программа, посвященная празднованию 80-летия Великой Победы!

