('Виртуозы России. Времена года. Вивальди. Гала-концерт при свечах с органом',
'https://afisha.yandex.ru/samara/concert/virtuozy-rossii-vremena-goda-vivaldi-gala-kontsert-pri-svechakh-s-organom-2025?source=rubric',
'Программа «#Временагодавивальди» предлагает совершить новые открытия в известных и любимых произведениях Антонио Вивальди. Впервые эти шедевры прозвучат для скрипки и органа в особой атмосфере при свечах. Слушателей помимо виртуозного исполнения ждет погружение в ассоциативный мир шедевров живописи, которые будут представлены на большом медиа экране. А ведущая — известный музыковед Елена Карлова откроет нам зашифрованные смыслы, и чувства, которые Вивальди заложил на века в свои шедевры. Незабываемым завершением этого концерта станут легендарные шедевры Баха — «Токката и фуга» ре минор для органа и «Чакона» Витали —Шарлье для альта и органа!

«Виртуозы россии | Русская скрипичная школа» — это всероссийский проект состоящий из серии гала-концертов скрипичной виртуозной музыки в исполнении звезд Российской сцены и молодых виртуозов-солистов «Мастерской Скрипичного Искусства» — художественный руководитель проекта — артист квартета имени Давида Ойстраха — Федор Белугин.

Проект создан для продолжения и преемственности великих скрипичных традиций. В нем принимают участие знаменитые российские музыканты и молодое поколение виртуозов, продолжателей традиций русской скрипичной школы, чьи имена также с большой вероятностью станут известны всем поклонникам скрипичной музыки.

Программа:
Бах — Токката и фуга ре минор для органа
Вивальди — Концерт для четырех скрипок и органа си минор.
Вивальди — «Времена года» цикл из четырех концертов для скрипки с органом:
— «Весна»
— «Лето»
— «Осень»
— «Зима»
Витали — Шарлье — «Чакона» для альта и органа

Исполнители:
Даниил Австрих (скрипка)
Фёдор Белугин (альт)
Анастасия Белугина (скрипка)
Никита Сенько (скрипка)
Андрей Похлебаев (скрипка)
Владислав Муртазин (орган)
Елена Карлова (ведущая)

Подробнее об исполнителях:
Белугин Фёдор — скрипач, альтист, дирижер, артист и один из основателей квартета им. Давида Ойстраха, доцент Московской государственной консерватории им. Чайковского, победитель международных конкурсов, художественный руководитель «Мастерской Скрипичного Искусства», основатель и главный дирижер камерного оркестра «Прометей». В качестве солиста и артиста квартета имени Давида Ойстраха, Федор ведет активную концертную деятельность. Концерты коллектива с неизменным успехом проходят в лучших концертных залах России, Европы, Азии и Южной Америки. Среди ангажементов квартета — выступления на сцене Парижской филармонии, в Wigmore Hall в Лондоне, Pierre Boulez Saal в Берлине, Wiener Konzerthaus и в Австрии, Академии Листа в Будапеште, Konzerthaus в Дортмунде, Palau de la Musica в Валенсии, Auditorio de Barcelona и других прославленных залах.

Даниил Австрих — скрипач, дирижер, победитель международных конкурсов, ученик профессора Виктора Третьякова, приглашенный профессор Высшей Школы Музыки в Карлсруэ и доцент Высшей Школы Музыки в Кёльне. Основатель платформы Mindfreemusic.

Как солист и ансамблист регулярно выступает в таких залах, как Карнеги -Холл в Нью Йорке, Вигмор-Холл в Лондоне, Библиотека Конгресса в Вашингтоне, зал Токио Сити Опера, Тонхалле в Цюрихе, Лайцхалле в Гамбурге, зал Женевской Консерватории, зал Изящных исскуств в Мехико и многих др.

Выступал под управлением дирижеров Юрия Симонова, Василия Синайского, Гинтараса Ринкявичуса, Павела Герштейна, Кирила Карабица, Фредерика Шаслена, а так же в ансамблях с такими музыкантами, как Ицхак Перльман, Дональд Вайлерстайн, Памела Франк, Антуан Тамести, Андрей Баранов, Нобуко Имаи, Василий Лобанов и многими др.

Анастасия Белугина (скрипка) родилась в 2009 г. в семье музыкантов. Занимается на скрипке в «Мастерской Скрипичного Искусства» в классе доцента Белугиной Марии Андреевны. Выступала в качестве солиста с камерными и симфоническими оркестрами под руководством Михаила Бенюмова, Павла Герштейна, Игоря Лермана, Владимира Кима, Федора Белугина, Александра Хургина, Андрея Рейна, Дмитрия Крюкова, Виктора Сороки. Выступала на многих известных российских сценах в ансамбле с такими музыкантами, как Андрей Баранов, Даниил Австрих, Матвей Блюмин, квартет имени Давида Ойстраха. Участница всероссийского телевизионного проекта «Вундеркинды» в двух номинациях «Скрипка» и «Балет». С 2019 года является солисткой «Мастерской Скрипичного Искусства». Стипендиат фонда «Новые имена» под руководством Дениса Мацуева.

Андрей Похлебаев (скрипка) — Победитель XV Международного конкурса классической музыки VIVA-MUSIC, лауреат 1 премии IV открытого Всероссийского конкурса скрипачей им. Турчаниновой и I Международного конкурса инструментального исполнительства им. Евы, Иосифа и Семена Коган. Массу наград Андрей получил в 2022 г., например, он оказался лауреатом V Международного конкурса скрипачей им. Янкелевича и стипендиатом «Новых имен». В 2023 победил в конкурсе солистов «Свет надежды», а также получил именную стипендию Международного благотворительного фонда Владимира Спивакова. С 2022 года солист «Мастерской Скрипичного Искусства».

Никита Сенько (скрипка). Родился в г. Железногорск (Красноярский край), где получил свое первое музыкальное образование. С 2019 года ученик «Мастерской скрипичного Искусства» — класс доцента Белугиной Марии Андреевны. Никита является лауреатом Всероссийских и Международных конкурсов. С 2020 года — солист «Мастерской Скрипичного Искусства». Выступал в качестве солиста с камерными и симфоническими оркестрами под руководством Павла Герштейна, Федора Белугина, Александра Хургина, Андрея Рейна, Дмитрия Крюкова. Играл на многих известных российских сценах, выступая в ансамбле с Андреем Барановым, Даниилом Австрихом, Федором Белугиным, Матвеем Блюминым.

Владислав Муртазин (орган). Народный артист республики Башкортостан, лауреат международных и всероссийских конкурсов пианистов, органистов, конкурса «Виртуоз-класс» Лозанской государственной консерватории, конкурса «Виртуоз-класс» Женевской консерватории. Имеет награды «Благодарность Президента РФ», «Благодарность председателя Государственного собрания-Курултая РБ».

