('Вечерняя музыка для органа',
'https://afisha.yandex.ru/samara/concert/vecherniaia-muzyka-dlia-organa-2025?source=rubric',
'Гении барокко, блистательные венские классики, романтики, композиторы Прекрасной эпохи и творцы ХХ века — люди во все времена обращались к духовной музыке, проводниками к ней станут вечные её друзья: орган и человеческий голос.

Приглашаем на традиционный концерт «Вечерняя музыка для органа». В руках заслуженной артистки РФ Людмилы Камелиной величественный орган будет звучать вместе с великолепным сопрано — лауреатом международных конкурсов Айсылу Сальмановой.

Звуки органа, которые могут длиться бесконечно долго, помогут отрешиться от всего земного и унесут в звездные миры иных пространств. Музыка подарит духовный свет и радость, полет мысли и свободу души...

