«Всероссийские филармонические сезоны»
Художественный руководитель и главный дирижёр — народный артист СССР, лауреат Государственной премии РФ Владислав Чернушенко

Русские народные песни в исполнении Капеллы неизменно покоряют слушателей многих стран мира и, конечно, российскую публику. Традиционные церковные песнопения афроамериканцев представляют собой уникальный пласт песенной культуры, который оказал влияние на многих композиторов и исполнителей, включая джазовых и рок-музыкантов. Спиричуэлс давно стали песенной классикой, они часто звучат с эстрады в исполнении академических коллективов.

Спиричуэлс (от англ. spiritual — духовный, религиозный) возникли во второй половине XVIII века в США. Они сочетают в себе элементы африканских исполнительских традиций с религиозными песнопениями белых переселенцев. Спиричуэлс и сейчас часто звучат с эстрады в исполнении классических и джазовых коллективов. Спиричуэлс значительно повлияли на зарождение, формирование и развитие джаза, многие из них до сих пор используются джазовыми музыкантами в качестве тем для импровизаций. Наиболее популярные спиричуэлс среди джазменов — Go Down, Moses и Down By The Riverside, а тeма When The Saints Go Marching In является своего рода гимном традиционного джаза (диксиленда). Спиричуэлс оказали большое влияние на творчество многих композиторов. Их интонациями пронизана опера Джорджа Гершвина «Порги и Бесс».

