Исполнители:
Государственная Академическая хоровая капелла им. Глинки (Санкт-Петербург).

Художественный руководитель и главный дирижёр — народный артист СССР, лауреат Государственной премии РФ Владислав Чернушенко.

Государственная академическая капелла Санкт-Петербурга — старейшее отечественное профессиональное музыкальное учреждение, которое повлияло на развитие всей русской культуры. Именно здесь появлялись и развивались основные направления музыкального искусства и образования. Вот уже несколько столетий первый русский профессиональный хор не перестает восхищать своим мастерством. Как и в прежние времена, критика относит хор Капеллы к числу лучших музыкальных коллективов мира.

Датой рождения Капеллы принято считать 12 августа 1479 года, когда основанный великим князем Московским Иваном III хор Государевых певчих дьяков принимал участие в службе освящения Успенского собора, первого каменного храма Московского кремля. Капелла заботливо хранит и восстанавливает «золотой фонд» своего классического репертуара. Силами Владислава Чернушенко и возглавляемого им коллектива возвращен к жизни ценнейший пласт отечественной культуры — творения русской духовной музыки. Важное место в репертуаре Капеллы занимают произведения современных композиторов.',
