('Закрытие сезона. Гала-концерт с участием ведущих солистов оперных театров Европы',
'https://afisha.yandex.ru/samara/concert/zakrytie-sezona-gala-kontsert-s-uchastiem-vedushchikh-solistov-opernykh-teatrov-evropy?source=rubric',
'Великолепная Екатерина Лёхина родом из Самары. Она окончила Самарское музыкальное училище им. Шаталова, потом продолжила свое образование в Академии хорового искусства в Москве. В 2005 году обладательница «хрустального» колоратурного сопрано стала победительницей на вокальном конкурсе «Санкт-Петербург» и была приглашена в венскую «Фольксоперу». В 2007 Екатерина выиграла один из самых престижных международных конкурсов «Опералия», где произошел любопытный эпизод: Пласидо Доминго, дирижировавший финальной программой, по какой-то причине не показал оркестру вступление, и знаменитую арию Лакме Екатерина допевала в полной тишине. Вручая ей первую премию, маэстро объяснил публике: «Понимаете, я заслушался, ... поэтому не успел показать оркестру вступление».

В 2011 году певица получила премию «Грэмми» в номинации «Лучшая оперная запись» за исполнение главной роли в опере финского композитора Кайи Саариахо «Любовь издалека». В настоящее время Екатерина Лёхина украшает своим исполнением лучшие сцены мира (в Вене, Париже, Мадриде, Монте-Карло, Лондоне, Мумбаи, Пекине и т.д.).

Алексей Курсанов (тенор) родился в Самаре, учился в музыкальном училище им. Шаталова (класс Виктора Козлова). В 2021 окончил Академию хорового искусства им. Попова (классы Лидии Абрамовой, Дмитрия Вдовина). В 2021–2022 — артист Молодежной оперной программы Большого театра.

В настоящее время Алексей Курсанов — солист Майнингенского государственного театра, выпускник оперной студии Баварской национальной оперы, приглашённый солист Баварской оперы, Кассельского театра и Россиниевского оперного фестиваля.

