'Погрузитесь в мир музыки Микаэла Таривердиева! Вас ждёт концертная программа в сопровождении камерного оркестра. В программе — инструментальные композиции из любимых кинофильмов и кульминация вечера — моноопера «Ожидание».

В основу «Ожидания» легла пронзительная поэма Роберта Рождественского «Ожидание (монолог женщины)», повествующая о чувствах женщины, тоскующей по возлюбленному. Написанная специально для Камерного театра Бориса Покровского и блистательной Марии Лемешевой, моноопера впервые прозвучала в 1985 году и с тех пор стала признанной классикой.

