'https://afisha.yandex.ru/samara/concert/gorod-piatigorsk?source=rubric',
'Долгожданное событие, гастрольный тур одной из самых ярких команд в сетке телевизионного вещания, среди юмористических программ, главного канала страны.

Команда города Пятигорск начала свой путь в 2009 году. Участие в играх межрегиональной лиги, в Краснодаре, что укрепило веру в собственные силы участников команды, что уже в 2011 году позволило выиграть бронзу Высшей лиги. В 2013 году команда становится Чемпионом Высшей лиги параллельно собрав всех больших Кивинов. Дважды побеждала в летних кубках чемпионов.

Одна из самых титулованных команд за всю историю Российского юмора.

Команда много лет неизменна в своем составе:
Ольга Картункова
