('Чиполлино',
'https://afisha.yandex.ru/samara/kids/chipollino-samarskii-teatr-opery-i-baleta?source=rubric',
'Балет «Чиполлино» создан для детей, но танцуют в нём по-взрослому. Недаром он не теряет популярности вот уже пятое десятилетие.

Всё началось с того, что итальянский писатель Джанни Родари в 1951 году сочинил сказку «Приключения Чиполлино», где действие происходит в мире живых и похожих на людей овощей, фруктов, цветов и зверей. Герой сказки, мальчик-луковка из бедной семьи, борется против жадных и наглых аристократов и побеждает с помощью своих друзей.

Десять лет спустя на основе этой сказки был сделан мультфильм на русском языке, который назывался просто «Чиполлино». Музыку к нему написал композитор Карен Хачатурян. Взяв эту музыку и музыку Хачатуряна к другим мультфильмам, хореограф Генрих Майоров создал балет «Чиполлино», который увидел свет 8 ноября 1974 года в Киеве. Спектакль собрал блестящие отзывы критики. Лучшие театры страны хотели видеть его на своих сценах, а лучшие артисты с удовольствием танцевали сказочные роли. Так происходит и по сей день.',
