('Concord Orchestra. Симфонические рок-хиты. Лучшее',
'https://afisha.yandex.ru/samara/concert/concord-orchestra-simfonicheskie-rok-khity-luchshee-tour?source=rubric',
'Когда рок встречается с симфонией — рождается нечто невероятное!

Готовьтесь к мощному музыкальному вихрю! Первый в мире танцующий симфонический оркестр — Concord Orchestra — приглашает вас на грандиозное шоу Симфонические рок-хиты «Лучшее». Это уникальный коктейль классической музыки и рок-энергии, который покорит сердца всех — и истинных фанатов рока, и ценителей симфонического звучания.

Всё, что вы любите — в одном шоу!

На одной сцене оживут культовые рок-хиты Nirvana, Scorpions, Linkin Park, Metallica, Thirty Seconds To Mars, Nightwish, Led Zeppelin, Limp Bizkit, Muse, Europe, Pink Floyd, Roxette, Queen, Evanescence, System of a Down, AC/DC, Bon Jovi и многих других. Это лучшие композиции за 10 лет гастролей Concord Orchestra — те самые мелодии, которые вы ждали! И, конечно же, совершенно новые произведения, которые прозвучат впервые. Энергия рок-хитов станет еще мощнее!

Это не просто концерт — это шоу на грани реальности! «Симфонические рок-хиты» — это взрыв эмоций, захватывающее путешествие сквозь вселенную легендарной рок-музыки!

Что делает это шоу Concord Orchestra уникальным?

Танцующий оркестр. Музыканты Concord Orchestra не просто играют — они двигаются в такт музыке, превращая каждую композицию в зрелищное представление. Без нот. Полное погружение в музыку — никаких пюпитров, никакого листания партитур. Все композиции исполняются наизусть, позволяя музыкантам чувствовать сцену и взаимодействовать с залом.

Фантастические спецэффекты. Огненная световая магия, гипнотический видеоряд и впечатляющие костюмы создают настоящий визуальный спектакль. Эмоции на максимум. Вы словно оказываетесь сразу на всех рок-концертах своей мечты, проживая каждую ноту, каждое движение, каждую вспышку света.

Это шоу — симбиоз прошлого, настоящего и будущего рока! Мощные аранжировки в исполнении оркестра переносят вас в эпоху классического рока, но при этом звучат современно и свежо. Живое исполнение позволяет зрителям насладиться музыкой и пережить величайшие моменты рок-историй на одном концерте.

Готовы испытать адреналин, драйв и чистую музыкальную магию? Тогда не пропустите!

Присоединяйтесь и ощутите симфонический рок в его лучшем воплощении на Concord Orchestra. Симфонические рок-хиты «Лучшее»!',
