Хуан Орлендис — фронтмен, жизнерадостный мультиинструменталист, вокалист, педагог. Он — вихрь энергии, музыкант, чья страсть к искусству зажигает сердца. В руках Хуана оживают бас-гитара, гитара, рояль и зажигательные латиноамериканские перкуссии. Его творчество пронизано кубинским духом: от зажигательных ритмов до мелодий, которые заставляют сердца биться быстрее.

