'Сольный концерт группы «Дела поважнее».

Творчество «Дела поважнее» — это постоянный поиск надежды среди головной боли повседневности: от бодрого поп-панка до меланхоличного мидвест-эмо, от пронзительных гитарных лид-партий до тихих акустических баллад.

