('Duduk & Golos',
'https://afisha.yandex.ru/samara/concert/duduk-golos-2025?source=rubric',
'Duduk &amp; Golos (этно-фьюжн) исполнит уникальную программу, в основе которой так ярко и самобытно звучит армянская народная музыка, унося слушателя к истокам, к природе и началу бытия. Сплетаясь с разными мировыми музыкальными традициями, музыка приобретает новые грани.

Музыканты передадут магию звучания дудука и голоса в сочетании с необычным инструментальным составом.

Исполнители:
Артём Тер-Оганнисян (дудук) — музыкант, завоевавший признание и любовь публики в Армении и России, продолжатель высокого искусства своих предков. Обладатель первых премий международных конкурсов;

Анна Авакян (вокал) — гран-при международного конкурса, исполнительница, чей бархатистый глубокий тембр обволакивает слушателя, создавая особую атмосферу восприятия музыки.',
