5217428966338560394,
'2025-05-31 19:00:00',
117),
('Джаз в доме Сивре. Global Jazz Quartet',
'https://afisha.yandex.ru/samara/concert/dzhaz-v-dome-sivre-global-jazz-quartet?source=rubric',
'Музыка квартета — это перекресток двух оригинальных мелосов и стилистик. Культур Ближнего Востока и Карибского бассейна.

Самвел Гаспарян сформировал квартет с артистами-обладателями «Грэмми», который успел захватить сердца слушателей во всём мире. Смешение необычных мелодий и жанров Ближнего Востока и Карибского бассейна никого не оставят равнодушными. 🤩

Лидер квартета — знаменитый пианист и композитор Самвел Гаспарян на международной сцене с 1998 года. Член Universal Music и Академии звукозаписи Грэмми, наставник Беркли (Абу-Даби). Записал 12 альбомов и гастролировал более чем в 40 странах мира.

Саксофонист, профессор, композитор и аранжировщик Ариэль Брингес получил три «Грэмми» с Чучо Вальдесом, Алехандро Сансом и Иваном Мелоном Льюисом. Его альбом Raíces En Colores отмечен премиями «Cubadisco» и Experience.

Басист Гастон Джойя — участник легендарных групп Irakere и The Afro-Cuban Messengers, лауреат Грэмми. В 2017 году получил орден за вклад в культуру Кубы.

Барабанщик Родни Баррето родился в Гаване. «Грэмми» получил в 2016-м с группой Чучо Вальдеса. В 2009 участвовал в знаменитом концерте «Мир без границ» в Гаване. Его первый сольный проект Drummer Negrito номинирован на латинскую Грэмми.',
'от 1 500 ₽',
'https://avatars.mds.yandex.net/get-afishanew/4768735/3ddb3f254dbb3c5a9b4ae691f02ffce1/s760x440',
5217428966338560394,
'2025-06-05 20:00:00',
118),
('Рок-острова',
'https://afisha.yandex.ru/samara/concert/rok-ostrova-2023-11-29?source=rubric',
'Кто-то скажет, что для группы масштаба «Рок-островов» площадка ресторана маловата. «Лужники» — вот это самое то. Но тем ценнее для поклонников возможность вот так камерно послушать любимые песни — «Белым снегом», «Костры» или «Встречи». И, конечно же, «Ничего не говори».

Когда-то, в конце 90-х, один известный на эстраде продюсер назвал группу «Рок-острова» «однодневкой». Владимир Захаров, бессменный лидер и вдохновитель коллектива, тогда ответил: поэтому мы и выступаем уже 15 лет! И вот прошло еще 15 лет (в 2016-м группа отметила 30-летие), время идет дальше, а «Рок-острова» продолжают регулярно выпускать альбомы и радовать поклонников (полку которых за эти годы только прибыло) новыми песнями.

На концертах «Рок-острова» всегда выступают «живьем». Владимир говорит: так легче, под «фанеру» ведь еще попасть нужно. А он не попадает. И петь умеет в любых условиях, потому никакие условия его не пугают.

Да и чего пугаться? Везде встречают хорошо. Вас ждут песни о любви и разлуке, боли и радости, стремления познать и найти себя в этой жизни.',
