'Самый атмосферный DR Фолк фест!

Для всех, кто скучал по звучанию гонгов и барабанов, волынок и хэндпанов, банджо, скрипок, флейт, контрабасов, арфы...

Для всех, кто хочет погрузиться в атмосферу фолка, этноса, крафта, и музыкальных традиций разных народов!

Вас ждут выступления самых талантливых и самобытных групп Самарской области, исполняющих музыку в самых разных направлениях: от зажигательных шотландских и ирландских мотивов до душевных русско-народных мелодий и страстных бразильских ритмов.

Время собирать рюкзаки, доставать походные кружки и звенящие браслеты, время выпить любимый крафт под звёздами, сидя рядом с близкими по духу людьми. Время сорвать голос, подпевая на концерте, и стоптать ноги от жарких танцев!',
