('Кай Метов',
'https://afisha.yandex.ru/samara/concert/kay-metov?source=rubric',
'Кай Метов — заслуженный артист России, певец, музыкант и композитор, автор многочисленных хитов. Его особенность — это завораживающий женские сердца голос, а также сочетание лирических мелодий, глубоких текстов и классических инструментов.

Кай Метов пишет от души и для души, не подчиняясь тенденциям современной эстрады, и подает свою музыку в интеллигентно-романтической манере. В творческом багаже артиста более десяти альбомов! Его репертуар настолько разнообразен, что каждый сможет найти себе любимую мелодию. Это хиты 90-х, которые звучали из каждого «Утюга» и звучат до сих пор на многих радиостанциях страны, это красивейшие инструментальные композиции, заставляющие нас задуматься об истинной любви, о смысле жизни, о прекрасных и порочных чувствах, людских страхах, переживаниях, мечтах. Они вырывают нас из обыденности и делают нашу жизнь прекраснее.

Каждый концерт Кая Метова — это всегда праздник, наполненный желанием жить, любить, и непременно танцевать, не только телом, но и душой. Position № 2, «Вспомни меня», «Роза чайная», «Где-то далеко идут дожди» и все любимые хиты!',
