'«Пузо и виртуозы Ленинграда» — это компания хорошо знакомых вам людей. Юность и значительную часть зрелости они провели в группе «Ленинград», Александра Попова по прозвищу «Пузо» все знают как исполнителя песен «Дорожная», «Баба не моего масштаба», «Обезьяна и орёл» и так далее.

Друзья некоторое время отдохнули и снова взялись за дело. Женские песни советской эстрады о любви, собранные и проверенные на совместных застольях, в их исполнении звучат так залихватски, обжигающе-трогательно, что устоять невозможно. Да вы и не стойте!

Человеческая жизнь, как известно, коротка, а минуты счастья ещё короче. Короче, пропускать такой концерт нельзя!',
