'https://afisha.yandex.ru/samara/concert/zatochka-2025-07?source=rubric',
'Тёплый ветер с запада принёс весточку, что лето будет не на шутку жарким, братцы! А жарким оно будет потому, что «Заточка» везёт мощнейшее шоу. Приготовили настолько особенный сет-лист, что даже самый придирчивый фанат захлопает в ладоши от радости. Тут и старые-добрые: «Новый шериф», «Моя роза», «Шапочка из фольги». Про последние релизы тоже не забудем! Ну и разбавим весь этот шумный праздник высокой лирикой: выдадим хитов под которые грех не повальсировать и не посадить мобилы, зажигая фонарики.

Так что, достопочтенные, отодвиньте в сторону знойные мечты о пикничках-шашлычках, есть вещи поважнее. Прелести гедонистической жизни никуда не убегут, а вот сольник «Заточки» — один и обещает быть неповторимым!',
