('Сироткин',
'https://afisha.yandex.ru/samara/concert/sirotkin-2025-07?source=rubric',
'А кто это у нас дома? Главный инди-исполнитель страны едет на фестиваль Roof Live.

Сироткин это не только название группы и имя ее основателя. Это направление в музыке, которое объединяет инди-мечтателей большой сцены. Голос того, кто придал свежий импульс этой большой музыкальной истории, зазвучит на крышах.

Концерты Сироткина каждый раз превращаются в теплое кино, по сценарию которого зрители незаметно становятся актерами и прямыми участниками действа. Все дело в магии лирики песен, которую принимаешь как легкий коктейль из грусти и меланхолии. От того идет единение с музыкантами, сценой и воздухом теплого вечера.

А еще это музыка про откровения и открытия. Названия песен сами говорят об этом — «Добрый злой», «Усталый праздник», «Кто у меня дома»... На концертах Сироткина можно признаваться в слабостях и сомнениях. Внутренний монолог зрителя и исповедь — неотъемлемые спутники группы.

Этим летом Сироткин выступит на Roof Live. Погрузи себя в музыку, как в любимое воспоминание — билеты уже на нашем сайте!',
