'Спектакль «Всё о женщинах» состоит из пяти новелл, переплетённых между собой тончайшей вязью судьбы.

В спектакле пять параллельно развивающихся историй, которые раскрывают разные грани взаимоотношений женщин разных возрастов и социальных ролей. Это и взаимоотношения мамы с дочкой, и маленьких девочек в детском саду только познающих жизнь, и подруг сплетниц, объединённых карьерой на работе, и неуемных юмористичных бабушек в престарелом доме, которые ревностно борются за любовь.

Спектакль «Всё о женщинах» — это театральный аттракцион, в котором три актрисы играют каждая по 5 ролей!

