'https://afisha.yandex.ru/samara/theatre_show/soldat-filat-i-korol-gishpanskii?source=rubric',
'Веселая, остроумная музыкальная сказка.

Жил в деревне парень Филат и был он беден. Потому его первым забрали в солдаты и отправили сразу на войну. Но проявил Филат чудеса храбрости и много врагов положил. Попал он в заграничные земли, в страну Гишпанию, к гишпанскому королю-самодуру и его коварной дочери Анете. Обманули его хитрые гишпанцы и посадили в темницу. Но выбрался оттуда Филат, поскольку был парень со смекалкой. Добрался, наконец, до родной деревни, где нашел себе невесту — самую скромную и работящую девушку, да еще красивее любой гишпанской принцессы!',
