145),
('Жил. Был. Дом.',
'https://afisha.yandex.ru/samara/cinema/teatr-v-kino-zhil-byl-dom?source=rubric',
'Оригинальный проект, задуманный народным артистом России, художественным руководителем МХТ имени А. П. Чехова Константином Хабенским в сотрудничестве с писателем Александром Цыпкиным.

Впервые премьерный показ спектакля состоится в формате киноверсии и будет показан в ста городах России ещё до официальной премьеры на театральной сцене. Это исключительная возможность для поклонников театрального искусства насладиться постановкой одного из ведущих драматических театров страны в формате кино, не покидая своего города. Режиссёр киноверсии — Валерий Спирин.

Как бы вы повели себя в тривиальных, будничных или наоборот критических ситуациях, если бы точно знали будущее? Какие решения приняли бы прямо сейчас, как бы поступили?

«Жил. Был. Дом.» — это одиннадцать историй, объединённых общим финалом. Финалом, меняющим абсолютно всё. Финалом, известным с первых минут. Смешные и грустные, захватывающие и до боли понятные и близкие любому человеку. Потому что они про каждого из нас, каждого, кто в этой жизни стоял перед выбором: верить или не верить в любовь, в дружбу, в судьбу, в счастье, в Бога.

«Жил. Был. Дом.» откроет перед зрителями двери многоэтажки в одном из городов России, где переплетаются судьбы 24 персонажей. В каждой квартире дома происходят события, на которые смотришь совершенно иначе, если знаешь о том, что ждёт всех героев всего через несколько часов. Ведь жизнь каждого находится под угрозой: всё зависит от того, успеют ли герои покинуть стены дома или нет. Именно в этот вечер происходят события, кардинально меняющие судьбы каждого героя.

Константин Хабенский: «Хочется рассказать такую историю, которая была бы близка и понятна абсолютно всем. Ведь в театр приходят разные люди, из разных социальных слоёв общества. Хочется, чтобы и партер, и балкон — все зрители увидели себя, свои радости, свои печали. Жанр нашего спектакля — «народная сказка для взрослых». По структуре она напоминает «Теремок», только помимо зверей в этом доме живут и люди. Сегодня хороших сказок с интересными диалогами, поворотами сюжета очень не хватает. Мы затеваем разговор про человеческие души. И не только про человеческие, ведь у животных тоже есть душа, которая требует внимания, уважения, но мы часто об этом забываем. Всех персонажей объединяет одно событие, которое повлияет на судьбу каждого героя. А какое — вы узнаете уже в зрительном зале».

Александр Цыпкин: «Идея Константина Юрьевича настолько драматургически выверенная и захватывающая, что мне оставалось только её не испортить своими сюжетами. Для меня это спектакль о счастье, несчастье и «не счастье», о том, что в любой момент времени мы делаем выбор, который приведёт нас к одному из трёх состояний. Иногда выбор необратим».

Театр оставляет за собой право вносить изменение в состав исполнителей.',
