('Летучая мышь',
'https://afisha.yandex.ru/samara/operetta/letuchaia-mysh-teatr-opery-i-baleta-samara?source=rubric',
'Оперетта «короля вальсов» Иоганна Штрауса «Летучая мышь» облетела сцены всех театров мира. Прекрасная, искрящаяся весельем музыка, остроумный текст и сюжет, складывающийся из череды забавных ситуаций, содержат, на радость сторонникам верности в браке, непременную в жанре оперетты мораль.

«Летучая мышь» – это вершина творчества Иоганна Штрауса. Остроумный сюжет оперетты строится по законам игры, обмана, веселого розыгрыша. Все прячутся под масками, каждый выдает себя за кого-нибудь другого: служанка за госпожу, поклонник за мужа, жена за любовницу своего мужа!

Музыка этой оперетты принадлежит к лучшим сочинениям легендарного короля вальсов Иоганна Штрауса-сына. Легкая, праздничная, пронизанная танцевальными интонациями, среди которых царствует именно вальс, она напоминает пенящееся шампанское. Мелодии оперетты ярко характеризуют действующих лиц. Среди ее персонажей на первом плане – Розалинда и Адель. Штрауса волновал романтический идеал женщины. В оперетте «Летучая мышь» интерес к женскому характеру определился с самого начала, здесь господствуют героини.

«Летучая мышь» – наиболее часто исполняемая оперетта композитора. Она неизменно присутствует в репертуаре всех театров оперетты и многих оперных театров. Уже больше века ее жизнерадостная, искрящаяся весельем музыка, остроумный текст и сюжет, складывающийся из череды забавных ситуаций, заражают зрителей энергией и оптимизмом.',
