('Игра в театр',
'https://afisha.yandex.ru/samara/excursions/igra-v-teatr-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Закулисье театра... Святая святых, волшебное место, куда не попадает обычный зритель.

Теперь у вас есть уникальная возможность не только посетить закулисье Самарского академического театра драмы, но и представить себя настоящими артистами. И, конечно, сделать множество фотографий в необычных локациях и даже на сцене театра драмы в роскошном наряде из спектакля!

На иммерсивной экскурсии «Игра в театр» вы сможете:
• войти в театр драмы со служебного входа, как артисты;
• побывать в театральных мастерских, где рождаются костюмы и декорации;
• заглянуть в костюмерные театра и гримерные актеров;
• спуститься на цокольный этаж и увидеть своими глазами легендарный поворотный круг-кольцо на катках от танка Т-34.
Кульминацией экскурсии станет фотосессия на исторической сцене театра драмы в подлинных костюмах из спектаклей.

Роли экскурсоводов исполнят актеры Самарского театра драмы Александр Бригаднов, Савва Зорин и Антон Черенков, которые поделятся с участниками экскурсии театральными байками и своими личными историями.

Внимание: выход на сцену театра возможен в сменной обуви или бахилах (предоставляются театром).
Проход на экскурсии через служебный вход (второе крыльцо после кассы со стороны Волги).',
