('Пиковая дама',
'https://afisha.yandex.ru/samara/opera/pikovaia-dama-samarskii-teatr-opery-i-baleta?source=rubric',
'Казалось бы, успех опере предрешен изначально: в литературной основе — программное произведение Пушкина, в музыкальной — сочинение Чайковского, в XIX веке ставшее новаторским по своей психологической глубине и драматизму. Но режиссер Михаил Панджавидзе не пошел по проторенному пути традиционной постановки. Следуя за общей канвой музыки и текста, он ставит спектакль, в первую очередь, о любви. На второй план уходят и прочие темы, и точность атрибутики — героям, одетым в исторические костюмы, совсем не обязательно дотошно соблюдать придворный этикет. Куда важнее чувствовать каждый изгиб сюжета и каждый музыкальный поворот.

Любовная линия Герман-Лиза-Елецкий в спектакле очерчена четко, но любовь в Петербурге особенная. Ведь режиссер в пушкинский сюжет помещает Петербург Достоевского. Грифоны, Петропавловка, чернота Невы, мосты, мосты, мосты… Этот город-призрак живет своей жизнью, последнее слово всегда за ним. И счастливая любовь здесь вряд ли возможна. Вот и умершего Германа невские воды погребают в своей глубине…

Постановка Михаила Панджавидзе получилась вполне классическая, но не лишенная оригинального, авторского взгляда, который был особо оценен экспертным советом премии «Золотая маска — 2016». Опера «Пиковая дама» представлена в номинациях «Лучший оперный спектакль», «Лучшая работа дирижера» (Александр Анисимов — главный дирижер театра и симфонического оркестра Республики Беларусь), «Лучшая работа режиссера» (Михаил Панджавидзе — главный режиссер театра), «Лучшая женская роль» (Ирина Крикунова — Лиза), «Лучшая мужская роль» (Михаил Губский — Герман).',
