('Rammproject',
'https://afisha.yandex.ru/samara/concert/rammproject-2025-09?source=rubric',
'Наши сочинские парни импортозамещают Rammstein во всех уголках страны. «Мама», «Солнце», «Ангел», «Москва» и другие хиты прозвучат в 100% оригинальном живом исполнении знаменитого трибьюта — группы Rammproject.

Потрясное шоу на открытом воздухе и оригинальный звук раскроют весь вкус легендарных хитов. Зарядись энергией для новых подвигов и противостояния повседневной рутине. Мы делаем музыку для ваших улыбок и радости в глазах.

Тебя ждёт:
— Два часа потрясающего живого звучания любимых песен Rammstein;
— Самые громкие хиты + свежие треки с последних альбомов;
— Голос, неотличимый от Линдеманна;
— Шоу по мотивам оригинала;
— Сумасшедший коллектив Rammproject.

Трибьют-шоу — шоу, в котором песни известных групп или артистов звучат в исполнении других музыкантов. Группы или артисты, чьи произведения исполняются, на мероприятии не присутствуют.',
