('Антон и Виктория Макарские',
'https://afisha.yandex.ru/samara/concert/anton-i-viktoriia-makarskie?source=rubric',
'«Живой Концерт» Виктории и Антона Макарских — интерактивное музыкальное действо, выходящее за пределы привычного формата эстрадного концерта и не имеющее аналогов среди проектов российских исполнителей.

На концерты Макарских приходят всей семьей! Песни, написанные для детей, песни из проекта «Святыни России», совместное исполнение лучших шедевров песенного наследия по просьбам старшего поколения создают незабываемую и радостную атмосферу объединения всех поколений семьи!

Антон и Виктория являются не только звёздами мюзиклов и телеэкрана, но и прекрасной супружеской парой. С первой минуты они влюбляют в себя зал тонким чувством юмора, необыкновенными голосами и искренним общением с публикой.

Выступление артистов невероятно поднимает настроение и всегда проходит только вживую в сопровождении талантливых музыкантов. Не случайно концерт называется «живым», так как именно зрители создают программу вечера и становятся полноценными участниками уникального концерта!

Концерт проходит под музыкальное сопровождение ансамбля (фортепиано, гитара, флейта, ударные, бас-гитара). В концерте не используется фонограмма.',
