('Криминальный бит',
'https://afisha.yandex.ru/samara/concert/kriminalnyi-bit-tour?source=rubric',
'Рэп-команде «Криминальный бит» исполняется 5 лет — достойный повод для празднования! Дерзкий и откровенный дуэт из Санкт-Петербурга по такому поводу отправляется в большой тур по России.

Участники команды «Криминальный бит» признаются, что главное в их творчестве — это атмосфера свободы и дух улиц. Свою личность музыканты не раскрывают, выступая в балаклавах, и подчёркивают, что для них важна пропитанная ностальгией музыка, которая отражает дух классического хип-хопа. В текстах — исключительно свой жизненный опыт, былые уличные приключения, проблемы и ситуации, знакомые каждому.

«5 лет в деле!» и мы едем в наш первый тур! 8 альбомов, более 150 треков, десяток мощных фитов и большая семья ценителей нашего творчества — впереди ещё больше песен и концертных шоу, — комментируют парни из «Криминального бита».

Музыка жизни и улиц, дух свободы и единения, реальные пацанские истории и биты — не пропусти шоу «5 лет в деле!».',
