('Plazma',
'https://afisha.yandex.ru/samara/concert/plazma-2023-11?source=rubric',
'Перестали просить у дедушки Мороза подарки? Вели себя плохо или не верите в волшебство? Макс Постельный и Роман Черницын — участники группы Plazma — уверяют: их желания исполнил именно Дед Мороз. Правда тут же добавляют: не все учел, а значит, нужно добиваться полной сатисфакции. Ну они-то, положим, были в этом году хорошими мальчиками: работали над новыми композициями и тэдэ. Так что вполне могут рассчитывать.

Поклонники Даля и русиано воскликнут: ах, это те самые, которые поют на английском? Подтверждаем: ага, те самые. Причем первые в России отважились. Конечно, до знаменитого министерского произношения «...Лец ми спик фром май харт ин инглиш» им далеко (и до подобной мировой славы). С другой стороны, политикой парни вроде не грезят. И думают исключительно на русском (аргумент?).

Думаете, слава и популярность приходят только если ты при московской прописке или деньгах? Дуэт Plazma родился в Волгограде. Роман Черницын и Макс Постельный учились вместе в школе и пели в одном детском ансамбле. После школы коллектив распался: кого от музыки отвадила армия, кого — жена. Парни остались вдвоем. Покорили столицу не сразу — попыток было несколько. Но в итоге все же получилось! Их дебютный альбом разошелся миллионным тиражом. А сингл Take My Love моментально попал во все чарты и хит-парады на первые места.

В 2020 году успеху группы исполнилось 20 лет. Менялся состав: приходили и уходили новые участницы. Были «русские» эксперименты: вместе с Алёной Водонаевой, например, несколько лет назад Plazma спела «Бумажное небо». Но не менялась основная идея: делать качественную музыку. И свой главный хит Take my love споют обязательно.',
