('Оркестр Поля Мориа: золотая коллекция из репертуара',
'https://afisha.yandex.ru/samara/concert/orkestr-polia-moria-zolotaia-kollektsiia-iz-repertuara?source=rubric',
'Программа «Оркестр Поля Мориа — золотая коллекция из репертуара маэстро» — это отличный шанс вживую услышать самые популярные произведения музыканта в фирменном звучании.

Музыка Поля Мориа известна всем нам по любимым советским телепередачам «В мире животных» и «Кинопанорама». Его творения вошли в жизнь каждого советского человека вместе с песнями Мирей Матье, Шарля Азнавура и Далиды. Его Гранд-оркестр получил всемирное признание, собирая многотысячные залы по всему миру.

Петербургский Большой эстрадно-симфонический оркестр под управлением пианиста Артёма Тетерина создан по золотому стандарту исполнительского состава Гранд-оркестра Поля Мориа.

Редко кому удается добиться максимально приближенного звучания. Артём Тетерин считает себя хранителем и почитателем великих французских традиций. Его аранжировки были оценены многими дирижёрами как в России, так и за рубежом.',
