('Однажды в Ёжкиных Кошках',
'https://afisha.yandex.ru/samara/theatre_show/odnazhdy-v-ezhkinykh-koshkakh-teatr-dramy-kamernaia-stsena?source=rubric',
'Если вы придете на спектакль с плохим настроением, уйдете - с улыбкой. Все герои деревни Ежкины Кошки ищут любовь: второклассники мечтают об отцах, их мамы - о надежных мужчинах, романтичная Дуся - о незнакомце в костюме и шляпе. В финале все герои найдут свое счастье, ведь жанр спектакля - лирическая комедия, придти на которую можно всей семьей.',
