('Загадочное убийство Белль',
'https://afisha.yandex.ru/samara/cinema/zagadochnoye-ubiystvo-bell?source=rubric',
'Пьер и его жена Клеа ведут размеренную жизнь в уютной французской глубинке. Он работает учителем, она заведует аптекой. Однажды к ним в гости приезжает дочка друзей — юная Белль, и её невинная красота пленяет весь город. Несколько дней спустя при таинственных обстоятельствах девушка погибает, а все улики указывают на хозяина дома. Кругом расползаются слухи. И теперь единственный шанс Пьера защитить своё честное имя — самому отыскать убийцу.',
