'https://afisha.yandex.ru/samara/cinema/poslednii-imperator?source=rubric',
'Китай, 1908 год. Двухлетний Пу И становится новым императором Поднебесной. Запертый в стенах Запретного города, он растет в роскоши и иллюзии власти, пока мир за пределами дворца стремительно меняется. Его судьба становится зеркалом эпохи: трон без империи, свержение, революция, война, лагеря и новая жизнь среди простых людей.',
