('Сущность. Семейный кошмар',
'https://afisha.yandex.ru/samara/cinema/sushchnost-semeynyy-koshmar?source=rubric',
'После смерти бабушки активная и успешная Розарио возвращается в родной дом. Из-за катаклизма в городе скорая помощь никак не может до него добраться, и девушке приходится провести ночь с усопшей. Сосед рассказывает, что бабушка очень скучала по внучке и молилась за неё каждую ночь. Но когда с наступлением темноты дом превращается в портал потустороннего и её начинает атаковать зловещая сила, Розарио понимает, кому молилась бабушка на самом деле. Теперь девушке предстоит столкнуться с демонической сущностью один на один. Чтобы спастись, ей нужно узнать тайны своего рода и прекратить раз и навсегда этот семейный кошмар.',
