('Горячее сердце',
'https://afisha.yandex.ru/samara/theatre_show/goriachee-serdtse-teatr-dramy-kamernaia-stsena?source=rubric',
'Комедия А.Н. Островского «Горячее сердце» — одна из самых веселых и озорных. Уморительно-смешные персонажи, остроумные диалоги, цветистая народная речь. Островский любит всех героев, он снисходителен даже к любителям горячительных напитков и — страшно сказать! — взяток. Разумеется, он бичует пороки, но любя. Ибо свое, родное, российское.

Спектакль в «Камерной сцене» не только о правосудии, как его понимают в дремучем городе Калинове, но и о любви, нерассуждающей, безрассудной, в отличие от расчетов, противных русской душе, о любви горячей, горячем сердце.',
'от 500 ₽',
