('На дне.doc',
'https://afisha.yandex.ru/samara/theatre_show/na-dne-doc?source=rubric',
'Документальный спектакль подразумевает, что в основе постановки лежит не художественное произведение, а реальный документ. Таким документом могут быть переписка в мессенджере, юридические бумаги, фотография или реальный разговор, услышанный в баре. Из подобных разговоров и строится спектакль. В январе 2024 года режиссер Дмитрий Крестьянкин общался с жителями Самары в разных барах, в том числе и легендарном «На Дне», в честь которого спектакль получил свое название. Из этих разговоров сложилась пьеса.
​
Спектакль «На дне.doc» — это попытка понять культурный код Самары, поделиться переживаниями о любви, поразмышлять о космосе, поболеть за «Крылья Советов» и понять, что реализм в театре — это очень опасно. Бар — это место встреч, место совместного переживания радостных и горестных событий, место честных разговоров, которые часто невозможны в иных ситуациях.',
'от 2 000 ₽',
'https://avatars.mds.yandex.net/get-afishanew/5109582/ee369db6524c407b86f1e1543d78cbd6/s760x440',
1154202497291966506,
'2025-05-14 00:00:00',
187),
('Аида',
'https://afisha.yandex.ru/samara/opera/aida-samarskii-akademicheskii-teatr-opery-i-baleta?source=rubric',
'«Аида» – одна из известных опер музыкального театра. Впервые поставленная в открывающемся Королевском оперном театре Каира 24 декабря 1871, она с феерическим успехом обошла все сцены мира.

В «Аиде» личная драма, полная острых коллизий, развертывается на широком красочном фоне монументальных массовых сцен, пышных шествий, танцев и гимнов. В образах жестоких жрецов Верди заклеймил ненавистное ему мракобесие церковников. Этим беспощадным силам противостоят душевная красота и нравственная стойкость Аиды и Радамеса: их любовь выдерживает все испытания, не отступая даже перед смертью. Опера наделена большим гуманистическим содержанием; она звучит как гимн высоким человеческим чувствам.

 Гениальные мелодии Верди, оркестровая красочность музыки, сквозное развитие драматического сюжета через столкновение ярких и сильных характеров и великолепное исполнение привлекают на эту постановку любителей оперы от мала до велика.',
'от 300 ₽',
'https://avatars.mds.yandex.net/get-afishanew/21422/ca3aa024e5958e5c22b5eaa760c379dd/s760x440',
8963580829962683892,
'2025-05-17 18:30:00',
188),
('Флория Тоска',
'https://afisha.yandex.ru/samara/opera/floriia-toska?source=rubric',
'«Тоска» — кровавая история о любви и ревности во времена наполеоновских войн — была основана на оглушительно успешной французской пьесе Викторьена Сарду, где в роли Флории Тоски блистала легендарная актриса Сара Бернар. Сегодня пьеса забыта, а оперу знают все, и это заслуга музыки. Пуччини воздействует на эмоции слушателя с безошибочной, почти манипулятивной точностью. Мы прощаем ему даже разрыв в стремительном беге событий, который он был вынужден сделать по просьбе первой исполнительницы роли Тоски, добавив арию «Vissi d’arte», в которой сопрано тщетно пытается достучаться до небес.

Последний романтик итальянской оперы, Джакомо Пуччини (1858–1924) сам прожил жизнь, достойную персонажа из либретто. Восемнадцатилетним юношей он прошел 20 километров пешком до Пизы, чтобы послушать «Аиду» Верди, и после этого решил во что бы то ни стало сам сделаться оперным композитором. И стал им, и обрел огромную популярность, и разбогател. Он любил карты и быстрые автомобили, заводил романы с певицами и был притчей во языцех среди критиков за свои слишком яркие и броские работы. Пуччини создал всего двенадцать опер, но треть из них у всех на слуху: «Богема», «Тоска», «Мадам Баттерфляй», «Турандот».

Нынешняя постановка «Тоски» в САТОБ — уже шестая по счету: опера ставилась здесь в 1933, 1941, 1950, 1963 и 1982 годах.',
'от 300 ₽',
