8963580829962683892,
'2025-05-16 18:30:00',
189),
('Маленький принц',
'https://afisha.yandex.ru/samara/theatre_show/malenkii-prints-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Странный народ эти взрослые... Погрязают в расчётах, власти, тщеславии, вредных привычках или просто утомительном напрасном труде, и считают, что это главное. Маленький принц, дитя с другой планеты, знает: зорко одно лишь сердце. У него есть искренняя любовь, крепкая дружба и ответственность за родную землю — по-настоящему самое важное в жизни. Новая постановка Яны Миносян по философской сказке Антуана де Сент-Экзюпери побуждает посмотреть на мир глазами ребёнка и сделать удивительные открытия в привычных вещах. «Ведь все взрослые сначала были детьми, только мало кто из них об этом помнит».',
'от 2 000 ₽',
'https://avatars.mds.yandex.net/get-afishanew/4487581/66c6f84d3d320a69a99cb6d49c4f3fbd/s760x440',
1154202497291966506,
'2025-05-17 00:00:00',
190),
('Есенин. Осколки разбитого зеркала',
'https://afisha.yandex.ru/samara/theatre_show/esenin-oskolki-razbitogo-zerkala-teatr-dramy-kamernaia-stsena?source=rubric',
'В 2025 году исполняется 130 лет со дня рождения гениального русского поэта Сергея Есенина и 100 лет со дня его смерти. В стране нет человека, который бы не слышал о нём, по всеобщему мнению, Есенин — выразитель русской души. Но народная любовь к поэту сыграла с ним злую шутку, Есенин стал частью фольклора, его лубочные портреты украшают сувенирную продукцию, коробки с пряниками и берёзовые доски. Поскольку стихи поэта очень музыкальны, их распевают на семейных застольях, не слыша в них трагических нот, не чувствуя драматических смыслов.
Один из самых противоречивых трагических русских поэтов в общественном сознании превратился в лирического певца родных пейзажей. Но страшный финал его жизни — результат конфликта с эпохой, в которой он не нашёл своего места, разочарования в своей мечте и самом себе.

Спектакль покажет великого поэта с неожиданной стороны, со всеми его противоречиями и ошибками. Но здесь нет выдуманных событий, ибо в основе пьесы — воспоминания современников Есенина, его родных, друзей, жён и возлюбленных.

История жизни поэта заставляет размышлять о природе творчества. Талант — явление какого порядка? Это дар Божий или наказание ? Можно ли пройти испытание медные трубами, или это не удаётся никому?
Театр надеется рассказать о русском гении ярко, нетривиально, захватывающе-интересно.

Спектакль в 2-х действиях.

В состав исполнителей могут быть внесены изменения без дополнительного уведомления.',
