'https://afisha.yandex.ru/samara/opera/kak-zaiats-strakh-pobedil-samarskii-teatr-opery-i-baleta?source=rubric',
'Композитор Сергей Баневич.
Либретто Олега Сердобольского и Сергея Баневича по «Сказке про храброго Зайца — длинные уши, косые глаза, короткий хвост» из сборника «Алёнушкины сказки» Дмитрия Наркисовича Мамина-Сибиряка.

«Родился зайчик в лесу и всё боялся. Треснет где-нибудь сучок, вспорхнет птица, упадет с дерева ком снега, — у зайчика душа в пятки.
Боялся зайчик день, боялся два, боялся неделю, боялся год; а потом вырос он большой, и вдруг надоело ему бояться».

Сергей Баневич сочинил оперу по «Сказке про храброго Зайца» весной 2016 года для артистов Академии молодых оперных певцов Мариинского театра.

Обратившись к сказке Мамина-Сибиряка, композитор и соавтор либретто, петербургский журналист и писатель Олег Сердобольский, дополнили ее сюжет и придумали новые действующие лица.

Веселая, поучительная и очень добрая история про бесстрашного Зайца в сочетании с замечательной музыкой доставит большую радость маленьким и взрослым зрителям.',
