('Два благородных дона',
'https://afisha.yandex.ru/samara/musical-play/dva-blagorodnykh-dona?source=rubric',
'«Два благородных дона» — это оммаж изящным временам Лопе де Веги, Шекспира, Тирсо де Молины, Гольдони… Их пьесы продолжают играть в театрах. Однако, к сожалению, ничего нового эти творцы уже не напишут. Авторы же решили в «Двух донах» вновь обратиться к атмосфере таких сюжетов, чтобы продлить на театральных подмостках сценические судьбы двух замечательных персонажей.

Вечно живые Дон Кихот и Дон Жуан — герои примерно одной эпохи. Нет сомнений в том, что они не могли не встретиться во времени и пространстве. Например, в начале XVII века на территории Испанской империи.

В сюжете пьесы есть всё: ирония, любовь, интрига, размышления, конфликт двух героев с разными мировоззрениями — «благородного рыцаря», который всегда верит в победу добра и разума, с более реалистичным идальго, который не готов тратить жизнь на заведомо проигрышную «борьбу с мельницами». Напряжение нарастает к финалу, после чего следует развязка, с обязательной долей грусти и оптимизма.',
