'https://afisha.yandex.ru/samara/art/kollektsioner-ivan-morozov-ot-van-goga-do-avangarda-muzei-fabriki-kukhni?source=rubric',
'Музей Фабрики-кухни — выставка работает по 30.04.25
Коллекционер Иван Морозов: от Ван Гога до авангарда — выставка работает по 28.09.25

Коллекционер Иван Морозов: от Ван Гога до авангарда

Выставка посвящена коллекции европейского и русского искусства Ивана Абрамовича Морозова (1871–1921). В центре проекта шедевры Винсента Ван Гога, Клода Моне, Поля Сезанна, Отона Фриеза, Анри Матисса, Андре Дерена и Огюста Эрбена. Они вступают в диалог с отечественной живописью 1900–1920-х годов, любимыми художниками коллекционера Ивана Морозова — Константином Коровиным и Александром Головиным, а также с произведениями Игоря Грабаря, Константина Сомова, Николая Милиоти, Мартироса Сарьяна и других авторов.

Выставка демонстрирует диалог французских и русских импрессионистов и символистов, специфику их национальных версий (Клод Моне и Константин Коровин, Анри Кросс и Александр Головин), а также — своего рода решительный, едва ли не революционный «прорыв» русских авангардистов за границы, очерченные новейшим французским искусством в лице его главных реформаторов: Сезанна, Ван Гога, Дерена, Матисса. Коллекционер Морозов в последние годы собирательства обратил внимание на художников-авангардистов из «Бубнового валета», и именно эта, важная сторона его коллекции, в большей степени приоткрыта на выставке в филиале Третьяковской галереи в Самаре. В экспозиции представлены работы Александра Куприна, Петра Кончаловского, Роберта Фалька и Наталии Гончаровой. Таким образом, зритель проделает путь, который прошла русская живопись в начале XX века, и который условно обозначен в названии выставки — от Ван Гога до авангарда.

Последние десять лет отмечены возросшим интересом к великим русским коллекционерам Ивану Морозову и Сергею Щукину, текстильным фабрикантам и видным благотворителям. Уникальный выставочный проект, предпринятый главными музеями — Государственным Эрмитажем, Государственным музеем изобразительных искусств им. А. С. Пушкина и Государственной Третьяковской галереей, которые сегодня хранят основную часть коллекции Морозовых, стартовал в 2016-м году, связав братьев Морозовых и Щукиных. Проект длился шесть лет и включил шесть выставок, прошедших с успехом в Париже, Петербурге и Москве. От этих грандиозных выставочных проектов 2016–2022 годов расходятся проекты-спутники, вдохновленные высочайшим уровнем московских коллекций, получивших мировое признание. К ним принадлежит и выставка «Коллекционер Иван Морозов: от Ван Гога до авангарда».

Для Морозова, как и для представителей других купеческих династий, коллекционирование было не просто данью моде. Идеи патриотизма и социально-ответственного бизнеса были неразрывно связаны с изучением европейской культуры и науки. Выставка «Коллекционер Иван Морозов: от Ван Гога до авангарда» подчеркивает роль меценатства в поддержке современного искусства и становлении музейных собраний.

Музей Фабрики-кухни

Весной 2024 года в Самаре открылся филиал Третьяковской галереи. С 2019 года проектировщики, строители и сотрудники Третьяковской галереи делали все, чтобы это важнейшее событие состоялось. Но главной причиной появления в Самаре филиала Третьяковки является само здание, в котором он расположен, — шедевр конструктивизма, здание в форме серпа и молота, творение одной из первых в России женщин-архитекторов и пример эффективности гражданского активизма и градозащиты — Фабрика-кухня завода имени Масленникова.

Фабрики-кухни — венец системы советского общественного питания 1920-х годов. Они должны были продемонстрировать советским гражданам идеальный образ коммунистического будущего: изобилие длинных линий раздач, стерильная чистота кухонь, гул машин и хор тысяч голосов посетителей просторных обеденных залов. В Самаре Фабрика-кухня открылась 1 января 1932 года, когда проект по строительству подобных гигантских комбинатов питания уже сворачивался. На протяжении XX века здание несколько раз перестраивалось, теряя свой первоначальный облик. К концу 1990-х годов в нем уже невозможно было разглядеть черты шедевра архитектуры эпохи конструктивизма. Сохранилась только форма перекрещенных серпа и молота. Над Фабрикой-кухней нависла угроза сноса, и лишь героическая борьба самарских общественников позволила спасти памятник от уничтожения, а затем создать в нем филиал Третьяковской галереи.

Экспозиция «Музея Фабрики-кухни» рассказывает об истории здания, его архитекторе Екатерине Максимовой, судьбе Фабрики-кухни после открытия и людях, которые с ней связаны. Пройдя символический путь от кухни, через линию раздачи к обеденному залу, посетители увидят артефакты, обнаруженные в ходе реставрации здания, вещи, переданные бывшими сотрудниками, экспонаты из коллекции потомков архитектора Екатерины Максимовой, предметы, связанные с советской кулинарией, и личные воспоминания посетителей и работников Фабрики-кухни. Параллельно с историей здания в экспозиции разворачивается история советского общепита и советской кулинарии в целом: от нарпитовской столовой и «Книги о вкусной и здоровой пище» до 6 квадратных метров кухни в хрущевке.',
