'История о детстве и творчестве Вольфганга Амадея Моцарта, — пожалуй самого известного композитора. Маленький мальчик, не зная нот, уже в 5 лет сочинил свой первый менуэт! Он нарушал правила, смеялся и веселился, и одновременно сочинял свою музыку. Как ему это удавалось? Говорят, у него была какая-то тайна.

