'https://afisha.yandex.ru/samara/cinema/artek-skvoz-stoletiya?source=rubric',
'Митя Неверовский — потомок легендарного генерал-лейтенанта. Но для своих родителей Митя — сплошная головная боль, он совершенно неуважительно относится к истории своей семьи, не ценит тот факт, что его предки — выдающиеся личности. Родители отправляют Митю в «Артек», где ему явно скучно, но желание выступить на «Артек-Арене» в рамках праздничного концерта — мечта для юного музыканта, и он хочет стать известным рэпером.
Правда, прежде чем его мечта осуществится, Мите предстоит пройти немало испытаний. Первое приключение начинается в 1925 году, куда Митя попадает вместе с Птичкиным, где они, совершив немало ошибок, проваливают миссию — за это петля времени забрасывает героев в 1812 год. Ход истории может быть нарушен настолько, что ни лагеря «Артек», ни самого Мити в настоящем может не оказаться.',
