('Поворот не туда',
'https://afisha.yandex.ru/samara/quest/povorot-ne-tuda-2024-12?source=rubric',
'В 2001 году в маленьком городке Инвиль все экраны пестрили новостью о найденной кассете с ужасающими кадрами!

Ваша компания туристов оказалась неподалеку от места событий, и теперь ваши жизни в опасности! В округе орудует семья каннибалов!

Этот городок пропитан истязающими криками о пощаде, молитвами и страхом! Страхом стать следующей жертвой!

Слышишь? Это скрежет древесины. Дыхание замирает, шаги приближаются, а сердце стучит так громко, что его можно услышать через закрытую дверь!

Теперь и ты чувствуешь этот страх… Беги или прячься…

Вас ждет:

	погружение с порога;
	двухуровневое помещение;
	постоянное преследование;
	ловушки.

Доступно 3 режима игры, отличаются уровнем контакта с актерами.

Режим Лайт 12+:

Без контакта

Режим для тех, кто любит погрузиться в атмосферу хоррора. Обстановка квеста на режиме Лайт располагает игроков к полному погружению в сюжет, но не подразумевает сильного психологического воздействия.

Вас не будут трогать. Вы сможете в полной мере проникнуться сюжетом и насладиться атмосферой нашего старого городка &quot;Инвиль&quot;.

Режим подойдет для всех, кто хочет взглянуть на страх издалека и предпочитает отсутствие физического взаимодействия .

Возрастное ограничение: 12+ с сопровождающим.

Режим Медиум 14+:

Все, что нужно для получения незабываемых эмоций. Тебе понравится. Здесь чисто, страшно, интересно и ужасно-красиво.

Обстановка квеста на режиме Медиум располагает игроков к полному погружению в сюжет. Твои представления о «Маньячке» будут вывернуты наизнанку.

Актеры покажут тебе настоящий театр ужаса. Возрастное ограничение: 14+

80 минут увлекательного, страшного и динамичного приключения в стиле хоррор. Приготовься к на100ящим эмоциям и постарайся продержаться до конца!

Режим Хард 18+:

С контактом

Настоящий ужас с бОльшим количеством актёров. Безумное взаимодействие с персонажами. Многообразие вариантов разделения участников. Вам не дадут долго находиться вместе, а также участникам придется жертвовать друг другом для дальнейшего прохождения квеста.

На данном режиме присутствует физический контакт . Вас могут схватить, повалить, ограничить в движении, приподнять и утащить.

Все необходимое, для любителей острых ощущений. Страшно, темно, жутко.

Возрастное ограничение: 18+

