'Юный Джейсон Вурхиз стал свидетелем того, как вожатая обезглавила его мать, голову которой он теперь хранит как воспоминание. Сойдя с ума, он убивает всех, кто появляется на берегу Хрустального озера.

Вы и ваши друзья решили провести выходные именно на том самом озере. Увидев уродливого человека, бегущего на вас, вы в панике убегаете вглубь ночного леса и натыкаетесь на заброшенный деревянный дом, но он заперт. Единственный шанс оттянуть встречу с Джейсоном – попасть в дом и найти укрытие...

