('Валак',
'https://afisha.yandex.ru/samara/quest/valak?source=rubric',
'У этого монастыря долгая история и довольно скверная.

После самоубийства монахини, церковь усомнилась в святости этого места и аббатство признали проклятым. Местные жители рассказывают страшные истории о новых обитателях заброшенного монастыря.

Община сектантов населила опустевшие стены и своими обрядами призывала демона Валака. Он приходит в образе той самой монахини и питается страхами туристов, заблудших на экскурсию под покровом ночи.

Что это? Придуманная легенда для процветания бизнеса среди экстремалов? Или подземелье психопатов?

Узнай правду, купив билет на популярную экскурсию нашего города...

Площадь квеста составляет 150 кв.м. и включает в себя 12 стилизованных под монастырь комнат, с множеством потайных лазов.

Падающие полки, двухуровневая локация, световые и звуковые эффекты нагнетающие жути прямо с порога! Всё, что нужно для незабываемого отдыха в кругу друзей.

