'Окунемся в придворную жизнь России второй половины 18 века: балы, маскарады, умопомрачительные наряды, фейерверки… Но все это — лишь маска, скрывающая клубок интриг, нить которого тянется к Екатерине Великой, удерживающей власть не только силой и умом, но и невероятной хитростью. Сможет ли княжна Тараканова, назвавшаяся истинной наследницей престола, уцелеть в противостоянии грозной императрице? Способен ли циничный фаворит Екатерины граф Орлов отказаться от своего положения при троне? История дает свои ответы на эти вопросы, но, по законам мюзикла, в происходящее вмешивается фантастическая любовь и, может быть, ей удастся переменить печальный исторический финал?',
