('Пальма 2',
'https://afisha.yandex.ru/samara/cinema/palma-2?source=rubric',
'Оставив большую авиацию, лётчик Вячеслав Лазарев с семьёй перебирается в глубинку, где продолжает летать, но теперь на маленьком винтовом АН-2. И жизнь Лазаревых идёт своим чередом, пока однажды в неё не врывается маленький медвежонок, которому Коля, сын лётчика, даёт кличку Мансур. Когда косолапого похищают местные браконьеры, ему на помощь приходит верная овчарка Пальма. Двум животным нужно найти дорогу домой через лес, полный диких зверей, охотников и прочих опасностей. А Лазаревым, отправившимися на поиски своих четвероногих друзей, предстоит вспомнить, что значит быть настоящей семьёй.',
