'VR-арена – шутер от первого лица с комбинацией свободного передвижения и виртуальной реальности без ограничений проводами.

Это командные сражения 5 на 5 или битва в формате «каждый сам за себя» с эффектом присутствия в виртуальном мире на игровом поле площадью 250 м².

