'https://afisha.yandex.ru/samara/ballet/balety-imperatorskogo-dvora-samarskii-teatr-opery-i-baleta?source=rubric',
'I отделение.
«Роман Бутона розы». Фантастический балет в 1 действии, в двух картинах.

Музыка Риккардо Дриго (1846 — 1930)
Хореография Мариуса Петипа (1818 — 1910)
Художник по костюмам Иван Всеволожский (1835 — 1909)
Постановка и хореографическая редакция Натальи Воскресенской

Музыкальный руководитель, дирижер-постановщик — Евгений Хохлов
Балетмейстер-постановщик — Наталья Воскресенская
Художник по костюмам — Татьяна Ногинова по эскизам Ивана Всеволожского
Художник по свету — Ирина Вторникова

Балет «Роман Бутона розы» в хореографии Мариуса Петипа. В 1903 году Петипа задумал эту постановку, которая должна была состояться в 1904 году на сцене Эрмитажного театра, но, к сожалению, этого не произошло. Лишь после смерти балетмейстера, в 1919 году, спектакль был поставлен Александром Ивановичем Чекрыгиным в бенефис Риккардо Дриго.

Сюжет балета прост и изящен. Он рассказывает о красавице клумбы — Бутоне розы, влюбившейся в мотылька — Сфинкса. Под влиянием чувств Бутон превращается в пышную Цветущую розу, но из-за измены Сфинкса с Настурцией начинает увядать. Однако благодаря вмешательству Королевы садов — Лилии, возвращается былая красота розы и любовь Сфинкса. Завершается романтическая история, как и многие балеты Мариуса Петипа, торжественным апофеозом.

II отделение.
«Времена года». Аллегорический балет в 1 действии, в 4 картинах.

Постановка победителей фестивального проекта «Русский балет навсегда» благотворительного фонда Илзе Лиепы

Музыка Александра Глазунова (1865 — 1936)
Хореография Мариуса Петипа (1818 — 1910)

I картина «Зима». Хореограф-постановщик — Елизавета Мазуркевич
II картина «Весна». Хореограф-постановщик — Лилия Симонова
III картина «Лето». Хореограф-постановщик — Марианна Рыжкина
IV картина «Осень». Хореограф-постановщик — Даниил Благов
Музыкальный руководитель, дирижер-постановщик — Евгений Хохлов
Художник-постановщик, художник по костюмам — Иван Складчиков
Художник по свету — Ирина Вторникова

Постановка балета «Времена года» на музыку Александра Глазунова совпала с юбилейной датой — 160 лет со дня рождения композитора. Замысел балета «Времена года» принадлежал Ивану Всеволожскому. Автором либретто и режиссером-постановщиком выступил один из лучших русских балетмейстеров, непревзойденный Мариус Петипа. По задумке балетмейстера каждое из времен года — это не просто поэтическая картина, а одушевленное действие. В картине зимы Снег и Снежинки танцуют вместе с Инеем и Льдом, пока два седых гнома не зажигают яркий костер, и тогда Царица-зима освобождает место Весне. Весну олицетворяет танец Розы, сопровождаемой Ласточками. Жаркое Лето — царство Колоса, Фавна, Сатиров и Озерных нимф. Осень — время сбора урожая. Эта сцена является кодой, которую по-другому называют «Вакханалия». В ней все времена года объединяются в общий танец.

Премьера балета состоялась 7 февраля 1900 года на сцене Эрмитажного театра в Санкт-Петербурге.',
