('Унесённые Голливудом',
'https://afisha.yandex.ru/samara/theatre_show/unesennye-gollivudom?source=rubric',
'Это история о создании шедевра мирового кинематографа и даже больше!

1939 год. Голливуд. Продюсер Дэвид Селзник останавливает съёмки нового фильма «Унесённые ветром», решив, что фильму нужен новый сценарий. Он запирается у себя в офисе и вызывает туда выдающегося сценариста Бена Хекта и гениального режиссёра Виктора Флеминга, единственных людей, по его мнению, способных спасти эту уже казалось бы безнадёжную картину. Но вот незадача — ни Хект, ни Флеминг не читали романа Маргарет Митчел. Но обратного пути у всех троих уже нет — через пять дней новый сценарий должен быть написан, чего бы им это не стоило!

5 дней. Один кабинет. Трое мужчин и книга. Отчаяние и вдохновение. Отрицание и принятие. Смех и слёзы. Миниатюры и танцы.. и как финал — готовый сценарий легендарного фильма, который завоюет 8 статуэток Оскара и станет самым кассовым в истории Голливуда вплоть до наших дней!

Удивительно то, что события, о которых идёт речь в спектакле, произошли на самом деле — именно так и появился сценарий фильма «Унесённые ветром». Единственное — мы не можем ручаться, что реальность была настолько смешной, как это получилось у нас.

Спектакль идёт с антрактом.

