'Действие спектакля переносит нас в советское время, в спектакле звучат шлягеры 1970–80-х годов. На сцене — декорации и атрибуты той эпохи.

В спектакле «Пять писем о любви» главная героиня — девочка Лена пишет школьные сочинения, в основу которых она берёт истории из своей жизни. Вспоминает она и свою детскую драму, как она в 5 лет подарила подруге свою куклу и потом это сильно переживала. Напишет историю соседки бабы Раи, которая прошла войну и живёт в одиночестве, но ухаживает за своей подругой, которая на войне страшно её предала. Расследует историю о школьной любви своей мамы, и старается сделать так, чтобы они вновь встретились. Расскажет и о своей несчастной школьной любви к мальчику Сереже.

Любовь идёт сквозной линией спектакля, помогает Лене избавиться от комплексов, пробуждает лучшие качества в человеке и побуждает взрослеть.

Спектакль проходит в формате квартирника, зрители смогут подпевать вместе с актёрами, которые вживую исполняют песни известных групп «Цветы», «Синяя птица», «Самоцветы», «Поющие гитары», «Песняры», «Лейся, песня!», Аллы Пугачёвой и другие.

