'https://afisha.yandex.ru/samara/standup/stand-up-po-zhenski-samara?source=rubric',
'Это шоу уже завоевало сердца зрителей Москвы, Питера и других регионов, пришло время покорять ваш город!

Лучшие девушки-комики региона и специальные гостьи из разных уголков России соберутся, чтобы дать зрителю свой отборный юмор, отпесочить бывших, пройтись по нынешним, а также смешно выговориться на наболевшие темы без цензуры.

