('Метель',
'https://afisha.yandex.ru/samara/theatre_show/metel-teatr-dramy-kamernaia-stsena?source=rubric',
'«Повести Белкина» — одни из самых загадочных произведений А. С. Пушкина, несмотря на всю легкость пера и увлекательность чтения. Наивному читателю они даже могут показаться незамысловатыми. Однако литературоведы по сей день ломают над ними головы. Например, кто такой Белкин? Не похоже, чтобы рассказчик, как он сам уверяет, «учился грамоте у дьячка». Слишком умен, образован, ироничен.

Многие современники Пушкина его повестей не оценили, считали их пустыми и даже водевильными. И самой «пустой» полагали «Метель».

Действительно, события в «Метели» развиваются неправдоподобным образом. Одни герои ничего не могут поделать против козней Судьбы, а другие соединяются сказочным образом. Но романтическая тема Рока, Провидения к моменту написания повестей настолько исчерпала себя, что Пушкин никак не мог серьезно к ней относиться. Потому ирония сквозит в каждой строчке повести.
Но тогда о чем она?

Прав был Ф. М. Достоевский: она — о русском семействе, о поэзии обычного существования простого человека, о России, о радости бытия. Эту светлую ноту попытался сохранить театр «Камерная сцена» в своем спектакле — и веселом, и грустном, и лукаво-ироничном. Все, как обычно бывает, когда говорим о чем-то кровно-близком и родном.',
