('Элья и Маргарита',
'https://afisha.yandex.ru/samara/theatre_show/elia-i-margarita?source=rubric',
'Рассказ И. Бабеля «Илья Исаакович и Маргарита Прокофьевна» – один из лучших у писателя, неожиданно задушевный и трогательный. Хотя Бабеля трудно упрекнуть в излишней трогательности.

