('Танцплощадка-1945',
'https://afisha.yandex.ru/samara/musical-play/tantsploshchadka-1945-kamernaia-stsena?source=rubric',
'В небольшом городке во дворе в августе 1945-го собрались соседи: учитель математики, раненый капитан и два совсем юных лейтенанта, вернувшихся домой после победы. С ними патефон и гитара. Разумеется, услышав звуки музыки, сбегаются девчонки, двор становится танцплощадкой. Девчонки выстраиваются в очередь, потому что после войны на десять девчонок по статистике мало ребят. Возникают соперничество, ревность, всё, как положено в двадцать лет. Но атмосфера августовского вечера 1945-го самая волшебная. Победа! Всё только начинается!',
