('Станционный смотритель',
'https://afisha.yandex.ru/samara/theatre_show/stantsionnyi-smotritel-teatr-dramy-kamernaia-stsena?source=rubric',
'С повестью А.С.Пушкина «Станционный смотритель» знаком каждый школьник, во всяком случае, все родители школьников. Сложилось впечатление, что «Повести Белкина» А.С. Пушкин писал специально для школяров, о чем сам великий поэт даже и помыслить не мог. В «Повестях Белкина» поставлены проблемы вселенского, космического масштаба, они касаются всех людей, живущих на Земле, всех, кто знает о великом нравственном законе внутри нас.

Каждый, преступивший этот закон, всегда осознает свое преступление, как бы он ни оправдывал себя . Кто вложил этот закон в наши души? Разумеется, Тот, кто создал нас. Для чего Он это сделал? Чтобы мы из приматов превратились в людей и стали достойными собеседниками Творцу. А иначе Ему и поговорить-то было бы не с кем.

Как все помнят, фабула «Станционного смотрителя» очень проста. Мелкий чиновник, находящийся на самой низкой ступени «Табели о рангах»,чиновник 14 класса (станционным смотрителям присвоили этот чин из милосердия, чтобы их меньше били, но бить их меньше не стали), воспитывает после смерти жены дочь Дунюшку, подростка необыкновенной красоты. Она — единственный смысл его жизни.

Но Дунюшку увозит в Петербург гусар, причем, с согласия самой девочки. Ей очень хочется увидеть другую жизнь. Вернуть дочь старику не удается, хотя он зимой пешком, через два месяца, добирается до Петербурга. Не отдаст Дуню гусар, это, во-первых, а, во-вторых, она сама не пожелает встретиться с отцом. И только через несколько лет потянет её в родные места, упадет она лицом, раскинув руки, на родной холм песка.

Неумолимый нравственный закон находит нас везде, в какой бы точке Вселенной мы бы ни находились. Об этом — спектакль «Камерной сцены», который театр хочет сделать пронзительным, трогающим душу зрителя, с яркими актерскими работами и тонким, атмосферным сценическим оформлением.',
