'К 80-летию великой Победы каждый театр России готовит спектакль как выражение великой благодарности героям, всем, завоевавшим эту победу, тем, кто сохранил страну и жизнь всем нам, ныне живущим, и тем, кто просто сумел выжить, несмотря ни на что.

