'https://afisha.yandex.ru/samara/ballet/krylia-vremia-liubit?source=rubric',
'Когда-то, на заре мироздания, в мире, лишённом любви и погружённом в холод и мрак, царила тишина. Серые люди-коконы населяли это безжизненное пространство, пока в небе не появились два белых парящих орла...

«Крылья. Время любить» — это хореографическая притча о любви, созданная на основе рассказа Заренкова «Орлы и Люди». Вместе с хореографом Александрой Тихомировой создатели спектакля рассказывают историю, в которой переплетаются судьбы двух пар — людей и птиц. Спектакль заставляет задуматься о вечных ценностях, о хрупкости человеческого счастья, о силе верности и любви, способной преобразить этот мир.',
