Спектакль «Скажи мне, что ты меня любишь...» основан на письмах прославленного певца «потерянного поколения» Эриха Марии Ремарка к звезде мирового кинематографа Марлен Дитрих.

К сожалению, ответных писем осталось мало, так как жена Ремарка сожгла их.

Эта история любви двух людей, которым никогда не суждено было быть вместе. Разные континенты, разные семьи, мировая известность. Немецкий писатель Э. М. Ремарк и кинодива М. Дитрих не принадлежали себе, эти люди были символом эпохи 20 столетия. Их роману суждено было осуществиться лишь на листах бумаги.

Эти письма создатели спектакля воплотили в жизнь, превратив их в диалоги, как будто души этих людей вели незримое миру постоянное общение, наполненное сильной любовью и привязанностью друг к другу.',
