('Мы едем в Америку',
'https://afisha.yandex.ru/samara/musical-play/my-edem-v-ameriku-mesto-deistviia?source=rubric',
'Музыкальный спектакль — обладатель Гран-при всероссийского фестиваля. Семья Мотла и их друзья вынуждены уехать из родной деревеньки в другой город и даже другую страну. На этом пути их ждут испытания и новые вызовы. Трогательные и смешные герои спектакля погрузят вас в свой мир, где о сложном говорят просто, о тяжёлом легко, но искренне и от чистого сердца! Вы посмотрите на жизнь глазами ребёнка, ведь главный герой — это Мальчик Мотл.

История обязательно закончится хэппи-эндом, и рецепт этого прост, ведь счастье внутри нас! «Перемена места — перемена счастья», так писал Шолом-Алейхем.',
'от 1 400 ₽',
'https://avatars.mds.yandex.net/get-afishanew/5109582/649bbafab85731184446af469bec4a8d/s760x440',
