'2025-05-16 00:00:00',
264),
('Эффект Пигмалиона',
'https://afisha.yandex.ru/samara/cinema/effekt-pigmaliona-2023?source=rubric',
'Роль неистового творца в драматургической конструкции спектакля отведена преуспевающему исполнителю бальных танцев, который решает «изваять» из нескладной представительницы городских низов виртуозную артистку.

Внутреннее и внешнее преображение героини происходит под музыку Иоганна Штрауса-сына, причём с произведениями «короля вальса» хореограф работает впервые в своей насыщенной творческой карьере.

«Эффект Пигмалиона» — первый за последние годы опыт обращения Бориса Эйфмана к комедийному (или, точнее сказать, трагикомедийному) жанру, признанным мастером которого является хореограф.

Неутомимый исследователь души, Борис Эйфман почерпнул обоснование названия нового балета в трудах по психологии, где понятие «эффект Пигмалиона» означает феномен влияния ожиданий на действительность. Так, человек, воспринимаемый другим как талантливый, будет ощущать уверенность в себе и добиваться успеха.

Поразительная пластичность личности, способной непредсказуемым образом меняться в соответствии с установками и мечтами, находит исчерпывающее художественное и философское раскрытие в спектакле Эйфмана.

Борис Эйфман: «Мы не знаем своих подлинных возможностей. Ведь человеческая природа бесконечно загадочна. Это сфера неисчерпаемых открытий. В каждом из нас заложена творческая энергия, наделяющая личность способностью к саморазвитию. Впрочем, чтобы изменить себя, человеку нередко нужен тот, кто готов пробудить в нём дремлющий потенциал. И, влияя на других, такие ваятели чужих судеб сами проходят через метаморфозы.

Балет «Эффект Пигмалиона» — хореографическая трактовка мифа о художнике и его творении, новый взгляд на тему сложной переплетённости и вечной нетождественности искусства и жизни.

В центре спектакля — дерзкая обитательница трущоб. Повстречав чемпиона по бальным танцам, она врывается в мир богатства и изумительного исполнительского мастерства. Здесь красота и обманчивая лёгкость движений достигаются жестоким трудом, а внешне притягательные плоды сценической славы не спасают от одиночества. Под руководством именитого танцовщика героине предстоит пройти путь пластического перевоплощения, которое, начавшись как курьёзный эксперимент, завершается настоящей драмой.

Необычайное упорство, душевные достоинства, прежде скрытые под накипью грубости, а также вспыхнувшая в девушке любовь к учителю и партнёру помогают ей вырасти в звезду. Однако фатальная пропасть между нищетой и роскошью может быть преодолена лишь в мире танца, уравнивающем жителей хижин и дворцов. В реальности же внутри нас навсегда остаётся мстительное прошлое, скрыться от которого не дано никому.

Чудесное превращение не приносит героине счастья. Гармония неизменно рассеивается вместе с остатками грёз. Но что есть сама жизнь, как не сон, порождённый томлением по недосягаемой мечте?…»',
