'https://afisha.yandex.ru/samara/cinema/geroychiki-nezvanyy-gost?source=rubric',
'Рома планирует выступить на школьном конкурсе и показать огромный звездолёт, собранный из конструктора. Игрушка, оборудованная по последнему слову техники, тут же привлекает внимание непрошеных гостей — таинственных космических пиратов. Они пытаются угнать звёздный корабль Друзьям Ромы — Пинки, Бублику, Генералу Де Кролю, Флаю, Глории, Ко-Ко и ящерице-ниндзя О-Раш — предстоит сразиться с пришельцами, а ещё проверить дружбу на прочность, поразмышлять о взаимопомощи, смелости, отваге, о праве на ошибку в жизни каждого, а ещё об умении прощать.',
