('Детектор лжи',
'https://afisha.yandex.ru/samara/theatre_show/detektor-lzhi-samarskii-akademicheskii-teatr-dramy-im-gorkogo?source=rubric',
'Искрометная комедия в исполнении актеров Самарского академического театра драмы им. Горького.

Комедия современного популярного драматурга В. Сигарева о людях, которые рядом с нами и могут быть нашими друзьями и соседями! Жизненный сюжет! Ироничный, смешной, который заставляет задуматься о своей жизни каждого зрителя!

Однажды пьяница-муж спрятал зарплату, а на утро не смог вспомнить куда... Жена в ярости вызывает гипнотизера, чтобы найти пропавшие деньги... Тут все началось и понеслось! Ну а потом... потом... можно ведь и жену проверить «на вшивость»! Эффект получился самый неожиданный и непредсказуемый! Эффект разорвавшейся бомбы!

Замечательная, искренняя и проникновенная игра звездных актеров заставляет зал, затаив дыхание, ловить каждое слово, каждый жест до самого финала!

В спектакле за веселым содержанием кроется глубокая сердечная история, и гипнотизер помогает не только найти запрятанные деньги, не только раскрыть семейные житейские тайны и секреты, но и вытаскивает на поверхность любовь и нежность, запрятанную очень глубоко даже от самих супругов!

Ведь любовь и семейное счастье - это то, ради чего следует жить!',
