'2025-06-01 12:00:00',
285),
('День рождения Золушки',
'https://afisha.yandex.ru/samara/musical-play/den-rozhdeniia-zolushki-teatr-dramy-kamernaia-stsena?source=rubric',
'Фольклорный сюжет о бедной девушке, чудесным образом встретившей своего Принца, бродит по миру многие века. Десятки авторов сочиняли свою версию этой истории. Сказку «Золушка» Шарля Перро обожают дети всех стран.

Театр «Камерная сцена» поставил спектакль по пьесе Лидии Андреевой «День рождения Золушки». Маленькие зрители увидят своих любимых героев: трогательную Золушку, ироничную Фею, несносную Мачеху и ее капризных дочек, смешного Короля, обожающего своего сына и, конечно, юного Принца, в которого не могла не влюбиться Золушка! Веселая музыкальная история с героями, одетыми в костюмы 17 века, позволят не только юным зрителям, но и их родителям погрузиться в атмосферу незабываемой театральной сказки.',
