'2025-06-04 11:00:00',
286),
('Щенок',
'https://afisha.yandex.ru/samara/theatre_show/shchenok-samarskii-teatr-gorod?source=rubric',
'По мотивам пьесы Анны Богачёвой и Елены Новиковой «Дуня, клоун и щенок».

Одинокая женщина Дуня работала диктором в Парке культуры имени отдыха, делала всякие там объявления, а голос у неё был очень красивый, а сама она была одинокая, потому что сидела в крошечной будке с маленьким микрофоном.

И вот Дуня нашла щенка, и назвала его Бобик, и привела его в свою квартирку, которая была ненамного больше той будки, в которой она работала. А потом она щенка потеряла. А щенок стал, конечно же, её искать, но нашёл вместо неё одинокого клоуна Мишу.

Билет необходим каждому зрителю, независимо от возраста.',
