('Баба Яга',
'https://afisha.yandex.ru/samara/theatre_show/baba-yaga-prokids?source=rubric',
'Спектакль от создателей «Алисы в стране чудес», шоу, покорившее сердца тысяч людей!

Наше новое театрализованное представление так же наполнено чудесами. В нём вы встретите настоящую магию, где в котле делает химические опыты «Баба Яга», в телефонной будке исчезает «Кощей», большие молнии от «Тесла» машины на сцене и много маленьких чудес.

Наши юные зрители будут частью шоу и будут помогать нам побеждать «Зло» «Добром», будет много интерактива и совместных опытов!

До встречи новым эмоциям вместе с нами.',
