292),
('Андре',
'https://afisha.yandex.ru/samara/theatre_show/andre-samarskii-teatr-gorod?source=rubric',
'Главному герою пьесы Андрэ 88 лет. Для своих лет он необычайно бодр, однако дают о себе знать признаки некой болезни, очень похожей на болезнь Альцгеймера. Болезнь прогрессирует, и это неотвратимо. Пьеса Зеллера — почти физическое воплощение процесса деформации сознания, его угасания.

Постепенная потеря памяти — это потеря семьи, родных, утрата связи с внешним миром. Все медленно исчезает из жизни главного героя — пространство, квартира, быт... Явь чередуется с картинами подсознания, разные ситуации возникают в различных интерпретациях — больного сознания и ясного ума.

Пьеса — обладатель трёх премий «Мольер», — была также номинирована на престижные театральные премии Theatre Awards UK и Evening Standart Theatre Awards.
«Папа» (Le pere) — вторая часть сценической трилогии «Мама»-«Папа»-«Сын».

88 лет — возраст выдающегося французского актёра Робера Ирша на момент премьеры пьесы, для которого Зеллером и была написана эта роль.',
'от 600 ₽',
'https://avatars.mds.yandex.net/get-afishanew/5098259/bbdd62c8925b1ba1a33f37570c5b3b7f/s760x440',
