'У Волка день рожденья... Но вот беда, у него совсем нет друзей. А какой же день рождения без друзей и подарков, которые они принесут? И решил Волк во что бы то ни стало найти себе настоящего друга! А с кем же ещё дружить Волку, как не с Зайцем? Да только Филин и Лиса постоянно мешают Волку и строят козни. Получится у него или нет найти себе друга, вы узнаете на спектакле. Спектакль будет интересен детям от трех лет и их родителям. Герои сказки будут постоянно вовлекать зрителей в стихию игры, будут петь и танцевать.

