'Легендарная игра «Мафия» обретает на ваших глазах новую форму. Теперь, вы можете не только быть за игровым столом в качестве игрока, а также, оказаться зрителем — непосредственным участником.

Действия разворачиваются в доме могущественного мафиози Мичелли Кальто, именно он приглашает вас в свои пенаты для особой игры.

Любовь, борьба, смех, драма, трагедия! Этот дом наполнен всеми чувствами и эмоциями принадлежащим людям. Почувствуйте себя частью истории, быть может у вас самостоятельно получится найти ключ к ответу над которым думают все герои истории? Всё только в ваших руках и только вы решаете кем оказаться в этой увлекательной истории:
— Игроком за столом? — да!
