('В поисках потерянного времени',
'https://afisha.yandex.ru/samara/theatre_show/v-poiskakh-poteriannogo-vremeni-domik-na-kryshe?source=rubric',
'Семейный спектакль-квест с применением онлайн-технологий «В поисках потерянного времени».

Вместе со смешными старичками, у которых злые волшебники украли время, зрители попадают в волшебное Часолесье. Они оказываются в Пещере бардака, Гаджетоландии, в Чулане обид и т.д., отгадывают различные головоломки и собирают потерянные минутки, чтобы старички снова стали молодыми.

Оказывается, что старички совсем и не старые — это ученики 2 класса, которые попусту теряли драгоценное время. Все испытания проводятся в отдельных помещениях. Оставшиеся в Часолесье зрители, могут подсказывать своим товарищам, болеть за них, так как все происходящее транслируются на большой экран. Спасая таких же детей, как и они, юные зрители учатся разбираться в часах, беречь свое время.

Головоломки рассчитаны на 3 возрастные группы: 1–4 года, 5–8 лет и 9–99 лет. Так что всей семье будет интересно, весело и познавательно!

После спектакля в 14:00 предлагаем деткам поучаствовать в мастер-классе «Часы своими руками», которые вы сможете забрать с собой! Ну а взрослых ждут интересные и полезные упражнения от психолога, которые помогут научиться самому и научить ребёнка распоряжаться своим временем, найти и сохранить баланс между трудом и отдыхом, научиться жить здесь и сейчас.',
