('Дом Бернарды Альбы',
'https://afisha.yandex.ru/samara/theatre_show/dom-bernardy-alby-arka?source=rubric',
'В глухом испанском селении, где солнце палит стены, а сплетни разгораются быстрее пожара, царит железная воля Бернарды Альбы. После смерти мужа она объявляет в доме траур на долгих восемь лет. Пять её дочерей, словно птицы в золотой клетке, мечтают о свободе, любви и хоть капле тепла. Но Бернарда неумолима: «Женщинам — полотно и иголки, мужчинам — мул и плетка».

Однако страсть не спрячешь за высокими стенами. Когда в селении появляется красавец Хосе Римлянин, тихий дом превращается в поле битвы. Ревность, запретная любовь и отчаянные попытки вырваться из-под материнской власти ведут к неожиданной развязке.

Почему стоит посмотреть?
— История в деталях — мы сохранили не только глубину и мощь оригинала, но и воссоздали костюмы того места и времени.
— Эмоциональный накал — вы увидите страсть, граничащую с безумием, неумолимую и безжалостную борьбу за своё счастье пяти незамужних женщин и непоколебимый религиозный фанатизм главной героини.
— Яркие характеры — от властной Бернарды до её мятежных дочерей, каждая из которых готова на всё ради любви.

Этот спектакль — как испанская жара: обжигает, но от него невозможно оторваться. Приходите и узнайте, чем закончится этот семейный бунт в безжалостной духоте Андалусии.

Дом Бернарды Альбы — место, где запреты рушатся, а страсти вырываются на свободу.',
