('Пиковая дама',
'https://afisha.yandex.ru/samara/immersive-theatre/pikovaia-dama-teatr-daniila-mironova?source=rubric',
'История о всепоглощающей одержимости и любви к азарту по мотивам одноимённой мистической повести Александр Пушкина.

Пьеса повествует о любителе карточных игр Германне, который узнаёт о существовании беспроигрышной комбинации из трех карт. Лёгкие деньги манят героя, он задумывает выведать секрет у его носительницы — старой графини.

Это первая постановка, которая пройдет в лофт-пространстве. Новый формат театра, когда зритель полностью погружается в процесс и сам становится частью представления.

