('Жизель',
'https://afisha.yandex.ru/samara/ballet/zhizel-russkii-moskovskii-balet?source=rubric',
'В маленькой деревушке средних веков живёт юная Жизель — чистая душой девушка, покоряющая всех своей искренностью и добротой. Она влюблена в Альберта, который представляется ей простым крестьянином.

В деревню приезжает Граф с дочерью Батильдой. Во время празднования Вальпургиевой ночи Жизель и Альберт обмениваются обручальными венцами, не подозревая о надвигающейся трагедии. Ночью Батильда раскрывает тайну — Альберт помолвлен с ней и является сыном графа. Жизель, узнав правду о возлюбленном, не в силах пережить предательство и сходит с ума от горя. Её чистая душа не выдерживает удара судьбы, и она умирает.

Ночью на кладбище появляются Виллисы — призрачные невесты, умершие до свадьбы. Мирта, главная вилиса, принимает Жизель в свой круг. Альберт, не в силах забыть свою возлюбленную, приходит на могилу Жизели.

С первыми лучами рассвета виллисы исчезают. Жизель прощает Альберта и, благословляя его, уходит в мир иной. Её любовь, победившая смерть, оставляет после себя вечный символ всепрощения и истинной преданности.',
