('Антоха МС',
'https://afisha.yandex.ru/samara/concert/antokha-ms-tour?source=rubric',
'Антоха МС (Антон Кузнецов) — один из самых узнаваемых и самобытных российских исполнителей, певец и трубач. Его музыка — это смесь рэгги, хип-хопа, джаза, танцевального фанка и оркестрового диско.

2024-й год стал по-настоящему прорывным для артиста. Антоха выпустил первый за пять лет лонгплей «Шик мола», которым открыл череду громких коллабораций: со Славой КПСС, Romanovskaya (певица и соавтор Cream Soda), The Hatters, Бастой, Лауд и пионерами поп-гранжа Ubel.

Летом артист выпустил EP Summer Live Session, на котором переосмыслил свои хиты с живым бэндом. Одним из самых ожидаемых релизов года стал кавер на песню Михея «Сука любовь», который первыми услышали гости летних фестивалей.

В 2024 у Антохи вышло три видео: клип на «Ритм сердца» удостоился 10 международных наград на кинофестивалях. Новый взгляд на песню «Множество путей» и клип «Хайвэй», снятый одним кадром в гостях у The Hatters.

Антоха МС отправляется в тур с лучшими хитами и свежими треками: петь, трубить и танцевать. Каждый концерт станет по-настоящему особенным и незабываемым.',
NULL,
'https://avatars.mds.yandex.net/get-afishanew/4487581/ebb93e60f6665e5c160f5679f3d9cd0a/s760x440',
6340270219114484733,
'2025-05-30 19:00:00',
332),
('Нурлан Сабуров',
'https://afisha.yandex.ru/samara/standup/nurlan-saburov-kontekst?source=rubric',
'Серьёзное лицо, обаяние, резкость и какая-то непривычная нам прямота, обескураживающая в начале, но совершенно точно очаровывающая каждого зрителя в зале. Тонкая грань юмора, где явно не захочется обвинить комика в оскорблении чувств кого бы то ни было. Нурлан делает это с таким изяществом и превосходством, что единственное, что остается зрителю — восхититься, расслабиться и посмеяться от души. Окаменеть от бесстрастности монологов и ожить от элегантной искренности — в этом вся суть выступлений Нурлана Сабурова.',
NULL,
