7080618738787822265,
'2025-05-18 20:00:00',
333),
('Пробка',
'https://afisha.yandex.ru/samara/theatre_show/probka-samarskaia-aktiorskaia-masterskaia-doktor-chekhov?source=rubric',
'Абсолютно неправдивая история.

Обыкновенная дорога в обыкновенном городе, одностороннее движение, автомобили едут обыкновенной кучей, не соблюдая разделительных полос, дорожных указателей. Жара. Три женщины за рулём, каждая хозяйка в своем авто. Каждая в своей машине поёт, подпевая работающему радио. У каждой своя волна. Все втроём тормозят, так как на дороге пробка...

Так начинается наша абсолютно неправдивая история о дружбе, жизни и любви...

Откровенные разговоры, курьёзные моменты и глубокая ирония, за которой скрывается много разных смыслов, ждут вас в этом спектакле.',
