('Леонид Кулаков',
'https://afisha.yandex.ru/samara/standup/leonid-kulakov-show?source=rubric',
'Леонид Кулаков — стендап комик, продюсер, основатель лейбла и бара Standup Patriki.

На протяжении всей своей карьеры был активным участником всевозможных комедийных проектов. Сегодня, Кулаков — это андеграунд комик, не приемлющий рамки, и более недоступен для зрителей на ТВ. Только вживую можно по-настоящему понять — Кто такой Леонид Кулаков?

Монологи Кулакова — это правда. Это искренность и честность комика перед зрителем на современную действительность через мощную призму юмора. Лёню смотрят, обсуждают, критикуют и восхищаются. Его сольники уже дали много шуму и немало просмотров. И мы приглашаем тебя на живой стендап, на сольный концерт Леонида Кулакова. Внутри безбашенной комедии тебя ждут новые эмоции, чувства и разные мысли.

Тебя ждёт шоу!

Сбор гостей за 30 мин до начала программы.
Возрастное ограничение 18+ (на входе потребуется паспорт).',
